use std::str::FromStr;

use rusqlite::types::{FromSql, FromSqlError, FromSqlResult, ToSql, ToSqlOutput, ValueRef};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Kind {
    Project,
    Pref,
    Work,
}

impl Kind {
    pub fn as_str(self) -> &'static str {
        match self {
            Kind::Project => "project",
            Kind::Pref => "pref",
            Kind::Work => "work",
        }
    }
}

impl FromStr for Kind {
    type Err = String;
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        match s {
            "project" => Ok(Kind::Project),
            "pref" => Ok(Kind::Pref),
            "work" => Ok(Kind::Work),
            other => Err(format!("알 수 없는 kind: {other}")),
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Status {
    Active,
    Superseded,
    Archived,
}

impl Status {
    pub fn as_str(self) -> &'static str {
        match self {
            Status::Active => "active",
            Status::Superseded => "superseded",
            Status::Archived => "archived",
        }
    }
}

impl FromStr for Status {
    type Err = String;
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        match s {
            "active" => Ok(Status::Active),
            "superseded" => Ok(Status::Superseded),
            "archived" => Ok(Status::Archived),
            other => Err(format!("알 수 없는 status: {other}")),
        }
    }
}

// DB 문자열 <-> enum 변환을 rusqlite에 알려 준다.
// 모르는 값이 들어 있으면 패닉 대신 에러로 돌려준다.
macro_rules! sql_enum {
    ($t:ty) => {
        impl ToSql for $t {
            fn to_sql(&self) -> rusqlite::Result<ToSqlOutput<'_>> {
                Ok(self.as_str().into())
            }
        }
        impl FromSql for $t {
            fn column_result(value: ValueRef<'_>) -> FromSqlResult<Self> {
                value
                    .as_str()?
                    .parse()
                    .map_err(|e: String| FromSqlError::Other(e.into()))
            }
        }
    };
}
sql_enum!(Kind);
sql_enum!(Status);

/// 새로 넣을 항목 (id, 시각 등은 DB가 채운다).
#[derive(Debug, Clone)]
pub struct NewItem {
    pub kind: Kind,
    pub scope: String,
    pub body: String,
    pub why: Option<String>,
    pub source: String,
}

#[derive(Debug, Clone)]
pub struct Item {
    pub id: i64,
    pub kind: Kind,
    pub scope: String,
    pub body: String,
    pub why: Option<String>,
    pub source: String,
    pub created_at: i64, // UTC 유닉스 초
    pub status: Status,
    pub supersedes_id: Option<i64>,
}

use std::path::Path;
use std::time::{SystemTime, UNIX_EPOCH};

use rusqlite::{Connection, Row, params};

use crate::item::{Item, Kind, NewItem, Status};

pub type Result<T> = std::result::Result<T, rusqlite::Error>;

/// 순서대로 적용되는 마이그레이션. 인덱스 + 1 이 곧 user_version.
const MIGRATIONS: &[&str] = &[r#"
    CREATE TABLE items (
        id            INTEGER PRIMARY KEY AUTOINCREMENT,
        kind          TEXT NOT NULL,
        scope         TEXT NOT NULL,
        body          TEXT NOT NULL,
        why           TEXT,
        source        TEXT NOT NULL,
        created_at    INTEGER NOT NULL,
        status        TEXT NOT NULL DEFAULT 'active',
        supersedes_id INTEGER REFERENCES items(id)
    );
"#];

pub struct Db {
    conn: Connection,
}

impl Db {
    pub fn open(path: &Path) -> Result<Self> {
        Self::init(Connection::open(path)?)
    }

    pub fn open_in_memory() -> Result<Self> {
        Self::init(Connection::open_in_memory()?)
    }

    fn init(conn: Connection) -> Result<Self> {
        conn.pragma_update(None, "foreign_keys", true)?;
        let db = Self { conn };
        db.migrate()?;
        Ok(db)
    }

    pub fn conn(&self) -> &Connection {
        &self.conn
    }

    pub fn user_version(&self) -> Result<i64> {
        self.conn.query_row("PRAGMA user_version", [], |r| r.get(0))
    }

    fn migrate(&self) -> Result<()> {
        let current = self.user_version()? as usize;
        for (i, sql) in MIGRATIONS.iter().enumerate().skip(current) {
            // 마이그레이션 하나는 트랜잭션 하나. 중간에 실패하면 버전도 안 오른다.
            let tx = self.conn.unchecked_transaction()?;
            tx.execute_batch(sql)?;
            tx.pragma_update(None, "user_version", (i + 1) as i64)?;
            tx.commit()?;
        }
        Ok(())
    }

    pub fn insert(&self, new: &NewItem) -> Result<i64> {
        self.conn.execute(
            "INSERT INTO items (kind, scope, body, why, source, created_at)
             VALUES (?1, ?2, ?3, ?4, ?5, ?6)",
            params![new.kind, new.scope, new.body, new.why, new.source, now_secs()],
        )?;
        Ok(self.conn.last_insert_rowid())
    }

    pub fn get(&self, id: i64) -> Result<Option<Item>> {
        let mut stmt = self.conn.prepare(
            "SELECT id, kind, scope, body, why, source, created_at, status, supersedes_id
             FROM items WHERE id = ?1",
        )?;
        let mut rows = stmt.query_map([id], row_to_item)?;
        rows.next().transpose()
    }

    pub fn list(&self, kind: Option<Kind>, scope: Option<&str>, status: Status) -> Result<Vec<Item>> {
        let mut stmt = self.conn.prepare(
            "SELECT id, kind, scope, body, why, source, created_at, status, supersedes_id
             FROM items
             WHERE status = ?1
               AND (?2 IS NULL OR kind = ?2)
               AND (?3 IS NULL OR scope = ?3)
             ORDER BY id",
        )?;
        stmt.query_map(params![status, kind, scope], row_to_item)?
            .collect()
    }
}

fn row_to_item(r: &Row<'_>) -> rusqlite::Result<Item> {
    Ok(Item {
        id: r.get(0)?,
        kind: r.get(1)?,
        scope: r.get(2)?,
        body: r.get(3)?,
        why: r.get(4)?,
        source: r.get(5)?,
        created_at: r.get(6)?,
        status: r.get(7)?,
        supersedes_id: r.get(8)?,
    })
}

pub fn now_secs() -> i64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn sample(kind: Kind, scope: &str, body: &str) -> NewItem {
        NewItem {
            kind,
            scope: scope.into(),
            body: body.into(),
            why: None,
            source: "test".into(),
        }
    }

    #[test]
    fn insert_then_get() {
        let db = Db::open_in_memory().unwrap();
        let id = db.insert(&sample(Kind::Project, "projA", "상태 관리는 단순하게")).unwrap();
        let item = db.get(id).unwrap().unwrap();
        assert_eq!(item.body, "상태 관리는 단순하게");
        assert_eq!(item.kind, Kind::Project);
        assert_eq!(item.status, Status::Active);
        assert!(db.get(999).unwrap().is_none());
    }

    #[test]
    fn list_filters() {
        let db = Db::open_in_memory().unwrap();
        db.insert(&sample(Kind::Project, "projA", "a")).unwrap();
        db.insert(&sample(Kind::Pref, "global", "b")).unwrap();
        assert_eq!(db.list(None, None, Status::Active).unwrap().len(), 2);
        assert_eq!(db.list(Some(Kind::Pref), None, Status::Active).unwrap().len(), 1);
        assert_eq!(db.list(None, Some("projA"), Status::Active).unwrap().len(), 1);
        assert_eq!(db.list(None, None, Status::Archived).unwrap().len(), 0);
    }

    #[test]
    fn migration_is_idempotent() {
        let path = std::env::temp_dir().join(format!("mnemo-test-{}", std::process::id()));
        let _ = std::fs::remove_file(&path);
        let db = Db::open(&path).unwrap();
        assert_eq!(db.user_version().unwrap(), MIGRATIONS.len() as i64);
        drop(db);
        let db = Db::open(&path).unwrap(); // 다시 열어도 에러 없이 같은 버전
        assert_eq!(db.user_version().unwrap(), MIGRATIONS.len() as i64);
        let _ = std::fs::remove_file(&path);
    }

    #[test]
    fn unknown_status_is_an_error_not_a_panic() {
        let db = Db::open_in_memory().unwrap();
        let id = db.insert(&sample(Kind::Work, "global", "x")).unwrap();
        db.conn().execute("UPDATE items SET status = 'weird' WHERE id = ?1", [id]).unwrap();
        assert!(db.get(id).is_err());
    }
}

pub mod db;
pub mod item;

pub use db::Db;
pub use item::{Item, Kind, NewItem, Status};

use crate::item::{Kind, NewItem};

/// 한 줄 형식:  kind:scope | 본문 | 이유(선택)
/// 빈 줄과 # 로 시작하는 줄은 건너뛴다.
/// 하나라도 잘못되면 (줄 번호, 사유) 목록을 돌려준다.
pub fn parse_lines(text: &str) -> Result<Vec<NewItem>, Vec<(usize, String)>> {
    let mut items = Vec::new();
    let mut errors = Vec::new();

    for (idx, line) in text.lines().enumerate() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        match parse_line(line) {
            Ok(item) => items.push(item),
            Err(e) => errors.push((idx + 1, e)),
        }
    }

    if errors.is_empty() { Ok(items) } else { Err(errors) }
}

fn parse_line(line: &str) -> Result<NewItem, String> {
    let mut parts = line.splitn(3, '|').map(str::trim);
    let head = parts.next().unwrap_or_default();
    let body = parts.next().filter(|s| !s.is_empty()).ok_or("본문이 없어요")?;
    let why = parts.next().filter(|s| !s.is_empty()).map(String::from);

    let (kind, scope) = head.split_once(':').ok_or("'kind:scope' 형식이어야 해요")?;
    let kind: Kind = kind.trim().parse()?;
    let scope = scope.trim();
    if scope.is_empty() {
        return Err("scope가 비어 있어요".into());
    }

    Ok(NewItem {
        kind,
        scope: scope.into(),
        body: body.into(),
        why,
        source: "import".into(),
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_good_lines() {
        let text = "# 주석
project:projA | 상태 관리는 단순하게 | 화면이 적음

pref:global | 번들 크기보다 유지보수 상태";
        let items = parse_lines(text).unwrap();
        assert_eq!(items.len(), 2);
        assert_eq!(items[0].why.as_deref(), Some("화면이 적음"));
        assert_eq!(items[1].why, None);
    }

    #[test]
    fn reports_line_numbers() {
        let text = "project:a | ok
bad line
foo:b | x
";
        let errs = parse_lines(text).unwrap_err();
        assert_eq!(errs.iter().map(|e| e.0).collect::<Vec<_>>(), vec![2, 3]);
    }
}

