use std::path::Path;
use std::time::{SystemTime, UNIX_EPOCH};

use rusqlite::{Connection, Row, params};

use crate::item::{Item, Kind, NewItem, Status};

pub type Result<T> = std::result::Result<T, rusqlite::Error>;

/// 순서대로 적용되는 마이그레이션. 인덱스 + 1 이 곧 user_version.
const MIGRATIONS: &[&str] = &[r#"
    CREATE TABLE items (
        id            INTEGER PRIMARY KEY AUTOINCREMENT,
        kind          TEXT NOT NULL,
        scope         TEXT NOT NULL,
        body          TEXT NOT NULL,
        why           TEXT,
        source        TEXT NOT NULL,
        created_at    INTEGER NOT NULL,
        status        TEXT NOT NULL DEFAULT 'active',
        supersedes_id INTEGER REFERENCES items(id)
    );
"#];

pub struct Db {
    conn: Connection,
}

impl Db {
    pub fn open(path: &Path) -> Result<Self> {
        Self::init(Connection::open(path)?)
    }

    pub fn open_in_memory() -> Result<Self> {
        Self::init(Connection::open_in_memory()?)
    }

    fn init(conn: Connection) -> Result<Self> {
        conn.pragma_update(None, "foreign_keys", true)?;
        let db = Self { conn };
        db.migrate()?;
        Ok(db)
    }

    pub fn conn(&self) -> &Connection {
        &self.conn
    }

    pub fn user_version(&self) -> Result<i64> {
        self.conn.query_row("PRAGMA user_version", [], |r| r.get(0))
    }

    fn migrate(&self) -> Result<()> {
        let current = self.user_version()? as usize;
        for (i, sql) in MIGRATIONS.iter().enumerate().skip(current) {
            // 마이그레이션 하나는 트랜잭션 하나. 중간에 실패하면 버전도 안 오른다.
            let tx = self.conn.unchecked_transaction()?;
            tx.execute_batch(sql)?;
            tx.pragma_update(None, "user_version", (i + 1) as i64)?;
            tx.commit()?;
        }
        Ok(())
    }

    pub fn insert(&self, new: &NewItem) -> Result<i64> {
        self.conn.execute(
            "INSERT INTO items (kind, scope, body, why, source, created_at)
             VALUES (?1, ?2, ?3, ?4, ?5, ?6)",
            params![new.kind, new.scope, new.body, new.why, new.source, now_secs()],
        )?;
        Ok(self.conn.last_insert_rowid())
    }

    /// 전부 넣거나 전부 취소한다 (트랜잭션 하나).
    pub fn insert_many(&self, items: &[NewItem]) -> Result<usize> {
        let tx = self.conn.unchecked_transaction()?;
        for it in items {
            self.insert(it)?;
        }
        tx.commit()?;
        Ok(items.len())
    }

    pub fn get(&self, id: i64) -> Result<Option<Item>> {
        let mut stmt = self.conn.prepare(
            "SELECT id, kind, scope, body, why, source, created_at, status, supersedes_id
             FROM items WHERE id = ?1",
        )?;
        let mut rows = stmt.query_map([id], row_to_item)?;
        rows.next().transpose()
    }

    pub fn list(&self, kind: Option<Kind>, scope: Option<&str>, status: Status) -> Result<Vec<Item>> {
        let mut stmt = self.conn.prepare(
            "SELECT id, kind, scope, body, why, source, created_at, status, supersedes_id
             FROM items
             WHERE status = ?1
               AND (?2 IS NULL OR kind = ?2)
               AND (?3 IS NULL OR scope = ?3)
             ORDER BY id",
        )?;
        stmt.query_map(params![status, kind, scope], row_to_item)?
            .collect()
    }
}

fn row_to_item(r: &Row<'_>) -> rusqlite::Result<Item> {
    Ok(Item {
        id: r.get(0)?,
        kind: r.get(1)?,
        scope: r.get(2)?,
        body: r.get(3)?,
        why: r.get(4)?,
        source: r.get(5)?,
        created_at: r.get(6)?,
        status: r.get(7)?,
        supersedes_id: r.get(8)?,
    })
}

pub fn now_secs() -> i64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0)
}

