use anyhow::Result;

use crate::db::Db;

#[derive(Debug, Clone, PartialEq)]
pub struct Scored {
    pub id: i64,
    /// 검색기마다 의미가 다르다 (FTS 는 bm25, 작을수록 좋음). 순위만 믿자.
    pub score: f64,
}

/// 질문을 받아 순위가 매겨진 결과를 돌려주는 검색기. Stage 6, 7 에서도 이걸 구현한다.
#[allow(async_fn_in_trait)]
pub trait Retriever {
    async fn search(&self, query: &str, k: usize) -> Result<Vec<Scored>>;
}

pub struct FtsRetriever<'a> {
    pub db: &'a Db,
}

/// 사용자 입력을 FTS5 MATCH 문법에 안전한 형태로 바꾼다.
/// 각 단어를 큰따옴표로 감싸고(내부의 " 는 "" 로) OR 로 잇는다. 단어가 없으면 None.
pub fn sanitize_query(input: &str) -> Option<String> {
    let tokens: Vec<String> = input
        .split_whitespace()
        .map(|t| t.replace('"', r#""""#))
        .filter(|t| !t.is_empty())
        .map(|t| format!(r#""{t}""#))
        .collect();
    if tokens.is_empty() { None } else { Some(tokens.join(" OR ")) }
}

impl Retriever for FtsRetriever<'_> {
    async fn search(&self, query: &str, k: usize) -> Result<Vec<Scored>> {
        let Some(q) = sanitize_query(query) else {
            return Ok(vec![]);
        };
        let mut stmt = self.db.conn().prepare(
            "SELECT items.id, bm25(items_fts)
             FROM items_fts JOIN items ON items.id = items_fts.rowid
             WHERE items_fts MATCH ?1 AND items.status = 'active'
             ORDER BY bm25(items_fts)
             LIMIT ?2",
        )?;
        let rows = stmt.query_map(rusqlite::params![q, k as i64], |r| {
            Ok(Scored { id: r.get(0)?, score: r.get(1)? })
        })?;
        Ok(rows.collect::<std::result::Result<Vec<_>, _>>()?)
    }
}

