use serde::Deserialize;

use crate::db::{Db, Result};

/// 평가 파일(JSON 배열)의 한 항목.
#[derive(Debug, Clone, Deserialize)]
pub struct Question {
    pub q: String,
    /// 정답 항목 id들. 정답 없음 유형은 빈 배열.
    pub answers: Vec<i64>,
    /// 유형 태그 (direct, paraphrase, ...)
    pub tag: String,
    /// 봉인 세트 여부. 기본 eval 에서는 제외된다.
    #[serde(default)]
    pub sealed: bool,
    #[serde(default)]
    pub note: String,
}

pub fn load_questions(json: &str) -> std::result::Result<Vec<Question>, serde_json::Error> {
    serde_json::from_str(json)
}

/// 정답 id 가 DB 에 실제로 있는지 확인한다. 없는 (질문, id) 목록을 돌려준다.
pub fn missing_answers(db: &Db, qs: &[Question]) -> Result<Vec<(String, i64)>> {
    let mut missing = Vec::new();
    for q in qs {
        for &id in &q.answers {
            if db.get(id)?.is_none() {
                missing.push((q.q.clone(), id));
            }
        }
    }
    Ok(missing)
}

/// 상위 k개 안에 든 정답의 비율. 정답이 없는 질문은 None.
pub fn recall_at_k(ranked: &[i64], answers: &[i64], k: usize) -> Option<f64> {
    if answers.is_empty() {
        return None;
    }
    let hit = answers.iter().filter(|a| ranked.iter().take(k).any(|r| r == *a)).count();
    Some(hit as f64 / answers.len() as f64)
}

/// 첫 정답 순위의 역수. 못 찾으면 0, 정답이 없는 질문은 None.
pub fn reciprocal_rank(ranked: &[i64], answers: &[i64]) -> Option<f64> {
    if answers.is_empty() {
        return None;
    }
    let pos = ranked.iter().position(|r| answers.contains(r));
    Some(pos.map_or(0.0, |p| 1.0 / (p as f64 + 1.0)))
}

