                    println!("{:<14}     (정답 없음 중 빈 결과 비율 {:.2})", "", e);
                }
            };
            line("전체", &report.overall);
            for (tag, row) in &report.by_tag {
                line(tag, row);
            }
        }
    }
    Ok(())
}

fn print_item(it: &Item) {
    println!("id         {}", it.id);
    println!("kind       {}", it.kind.as_str());
    println!("scope      {}", it.scope);
    println!("body       {}", it.body);
    println!("why        {}", it.why.as_deref().unwrap_or("-"));
    println!("source     {}", it.source);
    println!("status     {}", it.status.as_str());
    println!("created_at {} (UTC 초)", it.created_at);
}

