use std::future::Future;
use std::time::Duration;

use anyhow::{Context, Result, anyhow, bail};
use serde::Deserialize;

use crate::db::{Db, now_secs};

#[allow(async_fn_in_trait)]
pub trait Embedder {
    /// 어떤 모델로 만든 벡터인지. 벡터와 함께 DB에 저장한다.
    fn model_id(&self) -> &str;
    fn dim(&self) -> usize;
    async fn embed(&self, texts: &[String]) -> Result<Vec<Vec<f32>>>;
}

// ---------- 가짜 임베더: 같은 입력이면 항상 같은 벡터 ----------

/// 글자 2-gram 을 해시해서 dim 칸에 세는 가짜 임베더. 의미는 모르지만
/// 글자가 겹치는 문장끼리는 가까워서 테스트에 쓸 만하다.
pub struct FakeEmbedder {
    pub dim: usize,
}

impl Embedder for FakeEmbedder {
    fn model_id(&self) -> &str {
        "fake-bigram-v1"
    }
    fn dim(&self) -> usize {
        self.dim
    }
    async fn embed(&self, texts: &[String]) -> Result<Vec<Vec<f32>>> {
        Ok(texts.iter().map(|t| fake_vector(t, self.dim)).collect())
    }
}

fn fake_vector(text: &str, dim: usize) -> Vec<f32> {
    let chars: Vec<char> = text.to_lowercase().chars().filter(|c| !c.is_whitespace()).collect();
    let mut v = vec![0.0f32; dim];
    for w in chars.windows(2) {
        // FNV-1a
        let mut h: u64 = 0xcbf29ce484222325;
        for c in w {
            for b in (*c as u32).to_le_bytes() {
                h ^= b as u64;
                h = h.wrapping_mul(0x100000001b3);
            }
        }
        v[(h % dim as u64) as usize] += 1.0;
    }
    let norm = v.iter().map(|x| x * x).sum::<f32>().sqrt();
    if norm > 0.0 {
        v.iter_mut().for_each(|x| *x /= norm);
    }
    v
}

// ---------- f32 벡터 <-> BLOB ----------

pub fn vec_to_bytes(v: &[f32]) -> Vec<u8> {
    v.iter().flat_map(|x| x.to_le_bytes()).collect()
}

pub fn bytes_to_vec(bytes: &[u8], dim: usize) -> Result<Vec<f32>> {
    if bytes.len() != dim * 4 {
        bail!("벡터 길이가 이상해요: {}바이트 (기대 {}바이트)", bytes.len(), dim * 4);
    }
    Ok(bytes
        .as_chunks::<4>()
        .0
        .iter()
        .map(|c| f32::from_le_bytes(*c))
        .collect())
}

// ---------- 재시도 ----------

pub enum Attempt {
    /// 429, 5xx, 네트워크 오류: 기다렸다 다시
    Retry(anyhow::Error),
    /// 잘못된 키, 잘못된 요청: 다시 해도 소용없음
    Fatal(anyhow::Error),
}

/// 지수 백오프: 1회차 실패 후 base, 그다음 2*base, 4*base ...
pub async fn retry<T, F, Fut>(max_tries: u32, base: Duration, mut f: F) -> Result<T>
where
    F: FnMut() -> Fut,
    Fut: Future<Output = std::result::Result<T, Attempt>>,
{
    let mut tries = 0;
    loop {
        tries += 1;
        match f().await {
            Ok(v) => return Ok(v),
            Err(Attempt::Fatal(e)) => return Err(e),
            Err(Attempt::Retry(e)) if tries >= max_tries => {
                return Err(e.context(format!("{tries}번 시도했지만 실패했어요")));
            }
            Err(Attempt::Retry(_)) => {
                tokio::time::sleep(base * 2u32.pow(tries - 1)).await;
            }
        }
    }
}

// ---------- 실제 제공자 (OpenAI 호환 /embeddings 형식) ----------

pub struct HttpEmbedder {
    client: reqwest::Client,
    url: String,
    api_key: String, // Debug 를 derive 하지 않는다: 실수로 로그에 찍히지 않게
    model: String,
    dim: usize,
}

#[derive(Deserialize)]
struct EmbResponse {
    data: Vec<EmbData>,
}
#[derive(Deserialize)]
struct EmbData {
    index: usize,
    embedding: Vec<f32>,
}

impl HttpEmbedder {
    /// MNEMO_EMBED_URL, MNEMO_EMBED_KEY, MNEMO_EMBED_MODEL, MNEMO_EMBED_DIM 에서 읽는다.
    pub fn from_env() -> Result<Self> {
        let get = |k: &str| std::env::var(k).with_context(|| format!("환경변수 {k} 가 필요해요"));
        Ok(Self {
            client: reqwest::Client::builder().timeout(Duration::from_secs(30)).build()?,
            url: get("MNEMO_EMBED_URL")?,
            api_key: get("MNEMO_EMBED_KEY")?,
            model: get("MNEMO_EMBED_MODEL")?,
            dim: get("MNEMO_EMBED_DIM")?.parse().context("MNEMO_EMBED_DIM 은 숫자여야 해요")?,
        })
    }

    async fn once(&self, texts: &[String]) -> std::result::Result<Vec<Vec<f32>>, Attempt> {
        let res = self
            .client
            .post(&self.url)
            .bearer_auth(&self.api_key)
            .json(&serde_json::json!({ "model": self.model, "input": texts }))
            .send()
            .await
            .map_err(|e| Attempt::Retry(anyhow!("임베딩 요청 실패: {}", e.without_url())))?;

        let status = res.status();
        if status.as_u16() == 429 || status.is_server_error() {
            return Err(Attempt::Retry(anyhow!("임베딩 서버가 {status} 를 돌려줬어요")));
        }
        if !status.is_success() {
            return Err(Attempt::Fatal(anyhow!("임베딩 요청이 거절됐어요: {status}")));
        }

        let mut body: EmbResponse = res
            .json()
            .await
            .map_err(|e| Attempt::Fatal(anyhow!("임베딩 응답을 해석하지 못했어요: {}", e.without_url())))?;
        body.data.sort_by_key(|d| d.index);
        Ok(body.data.into_iter().map(|d| d.embedding).collect())
    }
}

impl Embedder for HttpEmbedder {
    fn model_id(&self) -> &str {
        &self.model
    }
    fn dim(&self) -> usize {
        self.dim
    }
    async fn embed(&self, texts: &[String]) -> Result<Vec<Vec<f32>>> {
        let out = retry(4, Duration::from_millis(500), || self.once(texts)).await?;
        if out.len() != texts.len() || out.iter().any(|v| v.len() != self.dim) {
            bail!("응답 개수나 차원 수가 기대와 달라요");
        }
        Ok(out)
    }
}

// ---------- 아직 임베딩이 없는 항목만 처리 (멱등) ----------

/// 이 모델의 벡터가 없는 active 항목을 batch 개씩 임베딩해 저장한다. 처리한 개수를 돌려준다.
pub async fn embed_missing(db: &Db, embedder: &impl Embedder, batch: usize) -> Result<usize> {
    let mut done = 0;
    loop {
        let rows: Vec<(i64, String)> = {
            let mut stmt = db.conn().prepare(
                "SELECT i.id, i.body FROM items i
                 LEFT JOIN embeddings e ON e.item_id = i.id AND e.model = ?1
                 WHERE e.item_id IS NULL AND i.status = 'active'
                 ORDER BY i.id LIMIT ?2",
            )?;
            stmt.query_map(rusqlite::params![embedder.model_id(), batch as i64], |r| Ok((r.get(0)?, r.get(1)?)))?
                .collect::<std::result::Result<_, _>>()?
        };
        if rows.is_empty() {
            return Ok(done);
        }

        let texts: Vec<String> = rows.iter().map(|(_, b)| b.clone()).collect();
        // 본문은 로그에 남기지 않고 개수만 남긴다
        eprintln!("임베딩 요청: {}개", texts.len());
        let vecs = embedder.embed(&texts).await?;

        let tx = db.conn().unchecked_transaction()?;
        for ((id, _), v) in rows.iter().zip(&vecs) {
            tx.execute(
                "INSERT INTO embeddings (item_id, model, dim, vec, created_at) VALUES (?1, ?2, ?3, ?4, ?5)",
                rusqlite::params![id, embedder.model_id(), v.len() as i64, vec_to_bytes(v), now_secs()],
            )?;
        }
        tx.commit()?;
        done += rows.len();
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::item::{Kind, NewItem};
    use std::cell::Cell;

    fn add(db: &Db, body: &str) -> i64 {
        db.insert(&NewItem { kind: Kind::Work, scope: "g".into(), body: body.into(), why: None, source: "t".into() }).unwrap()
    }

    #[test]
    fn bytes_roundtrip_and_length_check() {
        let v = vec![0.5, -1.25, 3.0];
        assert_eq!(bytes_to_vec(&vec_to_bytes(&v), 3).unwrap(), v);
        assert!(bytes_to_vec(&vec_to_bytes(&v), 4).is_err());
    }

    #[tokio::test]
    async fn fake_is_deterministic() {
        let e = FakeEmbedder { dim: 32 };
        let t = vec!["안녕 world".to_string()];
        assert_eq!(e.embed(&t).await.unwrap(), e.embed(&t).await.unwrap());
    }

    #[tokio::test]
    async fn embed_is_idempotent_and_invalidated_on_edit() {
        let db = Db::open_in_memory().unwrap();
        let a = add(&db, "first");
        add(&db, "second");
        let e = FakeEmbedder { dim: 16 };
        assert_eq!(embed_missing(&db, &e, 1).await.unwrap(), 2);
        assert_eq!(embed_missing(&db, &e, 1).await.unwrap(), 0);

        db.conn().execute("UPDATE items SET body = 'changed' WHERE id = ?1", [a]).unwrap();
        assert_eq!(embed_missing(&db, &e, 10).await.unwrap(), 1);
    }

    #[tokio::test]
    async fn retry_retries_then_succeeds() {
        let calls = Cell::new(0);
        let out = retry(3, Duration::from_millis(1), || {
            calls.set(calls.get() + 1);
            let n = calls.get();
            async move { if n < 3 { Err(Attempt::Retry(anyhow!("503"))) } else { Ok(n) } }
        })
        .await
        .unwrap();
        assert_eq!(out, 3);
    }

    #[tokio::test]
    async fn retry_gives_up_and_fatal_is_immediate() {
        let calls = Cell::new(0);
        let r: Result<()> = retry(3, Duration::from_millis(1), || {
            calls.set(calls.get() + 1);
            async { Err(Attempt::Retry(anyhow!("503"))) }
        })
        .await;
        assert!(r.is_err());
        assert_eq!(calls.get(), 3);

        calls.set(0);
        let r: Result<()> = retry(3, Duration::from_millis(1), || {
            calls.set(calls.get() + 1);
            async { Err(Attempt::Fatal(anyhow!("401"))) }
        })
        .await;
        assert!(r.is_err());
        assert_eq!(calls.get(), 1);
    }
}

