#[derive(Parser)]
#[command(version, about = "내 지식 DB")]
struct Cli {
    /// DB 파일 경로 (옵션 > MNEMO_DB 환경변수 > ./mnemo.db)
    #[arg(long, env = "MNEMO_DB", default_value = "mnemo.db", global = true)]
