    cmd: Cmd,
}

#[derive(Subcommand)]
enum Cmd {
    /// 항목 하나 추가
    Add {
        /// project / pref / work
        kind: Kind,
        /// 프로젝트 이름 또는 global
        scope: String,
        /// 본문 (사실 하나)
        body: String,
        /// 이유
