            let retriever = FtsRetriever { db: &db };
            for (i, hit) in retriever.search(&query, k).await?.iter().enumerate() {
                if let Some(it) = db.get(hit.id)? {
                    println!("{:>2}) [{}/{}] {}  ({:.2})", i + 1, it.kind.as_str(), it.scope, it.body, hit.score);
