use std::path::Path;
use std::time::{SystemTime, UNIX_EPOCH};

use rusqlite::{Connection, Row, params};

use crate::item::{Item, Kind, NewItem, Status};

pub type Result<T> = std::result::Result<T, rusqlite::Error>;

/// 순서대로 적용되는 마이그레이션. 인덱스 + 1 이 곧 user_version.
const MIGRATIONS: &[&str] = &[r#"
    CREATE TABLE items (
        id            INTEGER PRIMARY KEY AUTOINCREMENT,
        kind          TEXT NOT NULL,
        scope         TEXT NOT NULL,
        body          TEXT NOT NULL,
        why           TEXT,
        source        TEXT NOT NULL,
        created_at    INTEGER NOT NULL,
        status        TEXT NOT NULL DEFAULT 'active',
        supersedes_id INTEGER REFERENCES items(id)
    );
"#,
// v2: 키워드 색인. items 를 가리키는 external content 방식 + 동기화 트리거
r#"
    CREATE VIRTUAL TABLE items_fts USING fts5(
        body, why,
        content = 'items', content_rowid = 'id',
        tokenize = 'unicode61'
    );
    CREATE TRIGGER items_ai AFTER INSERT ON items BEGIN
        INSERT INTO items_fts(rowid, body, why) VALUES (new.id, new.body, new.why);
    END;
    CREATE TRIGGER items_ad AFTER DELETE ON items BEGIN
        INSERT INTO items_fts(items_fts, rowid, body, why) VALUES ('delete', old.id, old.body, old.why);
    END;
    CREATE TRIGGER items_au AFTER UPDATE ON items BEGIN
        INSERT INTO items_fts(items_fts, rowid, body, why) VALUES ('delete', old.id, old.body, old.why);
        INSERT INTO items_fts(rowid, body, why) VALUES (new.id, new.body, new.why);
    END;
    INSERT INTO items_fts(items_fts) VALUES ('rebuild');
"#,
// v3: 임베딩. 본문이 바뀌면 그 항목의 벡터는 무효 -> 트리거로 지운다
r#"
    CREATE TABLE embeddings (
        item_id    INTEGER NOT NULL REFERENCES items(id),
        model      TEXT NOT NULL,
        dim        INTEGER NOT NULL,
        vec        BLOB NOT NULL,
        created_at INTEGER NOT NULL,
        PRIMARY KEY (item_id, model)
    );
    CREATE TRIGGER items_body_changed AFTER UPDATE OF body ON items BEGIN
        DELETE FROM embeddings WHERE item_id = new.id;
    END;
"#];

pub struct Db {
    conn: Connection,
}

impl Db {
    pub fn open(path: &Path) -> Result<Self> {
        Self::init(Connection::open(path)?)
    }

    pub fn open_in_memory() -> Result<Self> {
        Self::init(Connection::open_in_memory()?)
    }

    fn init(conn: Connection) -> Result<Self> {
        conn.pragma_update(None, "foreign_keys", true)?;
        let db = Self { conn };
        db.migrate()?;
        Ok(db)
    }

    pub fn conn(&self) -> &Connection {
        &self.conn
    }

    pub fn user_version(&self) -> Result<i64> {
        self.conn.query_row("PRAGMA user_version", [], |r| r.get(0))
    }

    fn migrate(&self) -> Result<()> {
        let current = self.user_version()? as usize;
        for (i, sql) in MIGRATIONS.iter().enumerate().skip(current) {
            // 마이그레이션 하나는 트랜잭션 하나. 중간에 실패하면 버전도 안 오른다.
            let tx = self.conn.unchecked_transaction()?;
            tx.execute_batch(sql)?;
            tx.pragma_update(None, "user_version", (i + 1) as i64)?;
            tx.commit()?;
        }
        Ok(())
    }

    pub fn insert(&self, new: &NewItem) -> Result<i64> {
        self.conn.execute(
            "INSERT INTO items (kind, scope, body, why, source, created_at)
             VALUES (?1, ?2, ?3, ?4, ?5, ?6)",
            params![new.kind, new.scope, new.body, new.why, new.source, now_secs()],
        )?;
        Ok(self.conn.last_insert_rowid())
    }

    /// 전부 넣거나 전부 취소한다 (트랜잭션 하나).
    pub fn insert_many(&self, items: &[NewItem]) -> Result<usize> {
        let tx = self.conn.unchecked_transaction()?;
        for it in items {
            self.insert(it)?;
        }
        tx.commit()?;
        Ok(items.len())
    }

    pub fn get(&self, id: i64) -> Result<Option<Item>> {
        let mut stmt = self.conn.prepare(
            "SELECT id, kind, scope, body, why, source, created_at, status, supersedes_id
             FROM items WHERE id = ?1",
        )?;
        let mut rows = stmt.query_map([id], row_to_item)?;
        rows.next().transpose()
    }

    pub fn list(&self, kind: Option<Kind>, scope: Option<&str>, status: Status) -> Result<Vec<Item>> {
        let mut stmt = self.conn.prepare(
            "SELECT id, kind, scope, body, why, source, created_at, status, supersedes_id
             FROM items
             WHERE status = ?1
               AND (?2 IS NULL OR kind = ?2)
               AND (?3 IS NULL OR scope = ?3)
             ORDER BY id",
        )?;
        stmt.query_map(params![status, kind, scope], row_to_item)?
            .collect()
    }
}

fn row_to_item(r: &Row<'_>) -> rusqlite::Result<Item> {
    Ok(Item {
        id: r.get(0)?,
        kind: r.get(1)?,
        scope: r.get(2)?,
        body: r.get(3)?,
        why: r.get(4)?,
        source: r.get(5)?,
        created_at: r.get(6)?,
        status: r.get(7)?,
        supersedes_id: r.get(8)?,
    })
}

pub fn now_secs() -> i64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn sample(kind: Kind, scope: &str, body: &str) -> NewItem {
        NewItem {
            kind,
            scope: scope.into(),
            body: body.into(),
            why: None,
            source: "test".into(),
        }
    }

    #[test]
    fn insert_then_get() {
        let db = Db::open_in_memory().unwrap();
        let id = db.insert(&sample(Kind::Project, "projA", "상태 관리는 단순하게")).unwrap();
        let item = db.get(id).unwrap().unwrap();
        assert_eq!(item.body, "상태 관리는 단순하게");
        assert_eq!(item.kind, Kind::Project);
        assert_eq!(item.status, Status::Active);
        assert!(db.get(999).unwrap().is_none());
    }

    #[test]
    fn list_filters() {
        let db = Db::open_in_memory().unwrap();
        db.insert(&sample(Kind::Project, "projA", "a")).unwrap();
        db.insert(&sample(Kind::Pref, "global", "b")).unwrap();
        assert_eq!(db.list(None, None, Status::Active).unwrap().len(), 2);
        assert_eq!(db.list(Some(Kind::Pref), None, Status::Active).unwrap().len(), 1);
        assert_eq!(db.list(None, Some("projA"), Status::Active).unwrap().len(), 1);
        assert_eq!(db.list(None, None, Status::Archived).unwrap().len(), 0);
    }

    #[test]
    fn migration_is_idempotent() {
        let path = std::env::temp_dir().join(format!("mnemo-test-{}", std::process::id()));
        let _ = std::fs::remove_file(&path);
        let db = Db::open(&path).unwrap();
        assert_eq!(db.user_version().unwrap(), MIGRATIONS.len() as i64);
        drop(db);
        let db = Db::open(&path).unwrap(); // 다시 열어도 에러 없이 같은 버전
        assert_eq!(db.user_version().unwrap(), MIGRATIONS.len() as i64);
        let _ = std::fs::remove_file(&path);
    }

    #[test]
    fn unknown_status_is_an_error_not_a_panic() {
        let db = Db::open_in_memory().unwrap();
        let id = db.insert(&sample(Kind::Work, "global", "x")).unwrap();
        db.conn().execute("UPDATE items SET status = 'weird' WHERE id = ?1", [id]).unwrap();
        assert!(db.get(id).is_err());
    }
}

