use std::cmp::{Ordering, Reverse};
use std::collections::BinaryHeap;

use anyhow::Result;

use crate::db::Db;
use crate::embed::{Embedder, bytes_to_vec};
use crate::search::{Retriever, Scored};

/// 코사인 유사도. 영벡터는 0.0 으로 정했다 (0 으로 나누면 NaN 이 퍼지니까).
pub fn cosine(a: &[f32], b: &[f32]) -> f32 {
    let dot: f32 = a.iter().zip(b).map(|(x, y)| x * y).sum();
    let na = a.iter().map(|x| x * x).sum::<f32>().sqrt();
    let nb = b.iter().map(|x| x * x).sum::<f32>().sqrt();
    if na == 0.0 || nb == 0.0 { 0.0 } else { dot / (na * nb) }
}

/// 방법 1: 전부 정렬한 뒤 자른다. O(n log n). 점수 내림차순.
pub fn top_k_sort(mut scored: Vec<(i64, f32)>, k: usize) -> Vec<(i64, f32)> {
    scored.sort_by(|a, b| b.1.total_cmp(&a.1));
    scored.truncate(k);
    scored
}

/// f32 를 힙에 넣으려고 감싼 타입. total_cmp 로 전순서를 준다.
#[derive(Debug, Clone, Copy)]
struct F(f32);

impl PartialEq for F {
    fn eq(&self, other: &Self) -> bool {
        self.cmp(other) == Ordering::Equal
    }
}
impl Eq for F {}
impl PartialOrd for F {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}
impl Ord for F {
    fn cmp(&self, other: &Self) -> Ordering {
        self.0.total_cmp(&other.0)
    }
}

/// 방법 2: 크기 k 짜리 최소 힙. 지금까지의 상위 k개 중 꼴찌만 들고 있다가, 더 좋은 게 오면 교체. O(n log k)
/// 결과는 점수 내림차순.
pub fn top_k_heap(scored: impl IntoIterator<Item = (i64, f32)>, k: usize) -> Vec<(i64, f32)> {
    let mut heap: BinaryHeap<Reverse<(F, i64)>> = BinaryHeap::with_capacity(k + 1);
    for (id, s) in scored {
        if heap.len() < k {
            heap.push(Reverse((F(s), id)));
        } else if let Some(Reverse((worst, _))) = heap.peek()
            && s > worst.0
        {
            heap.pop();
            heap.push(Reverse((F(s), id)));
        }
    }
    let mut out: Vec<(i64, f32)> = heap.into_iter().map(|Reverse((F(s), id))| (id, s)).collect();
    out.sort_by(|a, b| b.1.total_cmp(&a.1));
    out
}

/// 이 모델로 만든 active 항목의 벡터를 전부 읽는다.
pub fn load_vectors(db: &Db, model: &str) -> Result<Vec<(i64, Vec<f32>)>> {
    let mut stmt = db.conn().prepare(
        "SELECT e.item_id, e.dim, e.vec FROM embeddings e
         JOIN items i ON i.id = e.item_id
         WHERE e.model = ?1 AND i.status = 'active'",
    )?;
    let rows = stmt.query_map([model], |r| Ok((r.get::<_, i64>(0)?, r.get::<_, i64>(1)?, r.get::<_, Vec<u8>>(2)?)))?;
    let mut out = Vec::new();
    for row in rows {
        let (id, dim, blob) = row?;
        out.push((id, bytes_to_vec(&blob, dim as usize)?));
    }
    Ok(out)
}

pub struct VectorRetriever<'a, E: Embedder> {
    pub db: &'a Db,
    pub embedder: &'a E,
}

impl<E: Embedder> Retriever for VectorRetriever<'_, E> {
    async fn search(&self, query: &str, k: usize) -> Result<Vec<Scored>> {
        let q = self.embedder.embed(&[query.to_string()]).await?.remove(0);
        let all = load_vectors(self.db, self.embedder.model_id())?;
        let scored = all.iter().map(|(id, v)| (*id, cosine(&q, v)));
        Ok(top_k_heap(scored, k)
            .into_iter()
            .map(|(id, s)| Scored { id, score: s as f64 })
            .collect())
    }
}

