use std::collections::HashMap;

use anyhow::Result;

use crate::search::{Retriever, Scored};

/// 여러 순위 목록을 RRF 로 합친다. 점수 = Σ 1/(k + 순위), 순위는 1부터.
/// 점수 내림차순으로 돌려주고, 점수가 같으면 id 가 작은 쪽이 먼저 (결과가 매번 같도록).
pub fn rrf(lists: &[Vec<i64>], k: f64) -> Vec<(i64, f64)> {
    let mut score: HashMap<i64, f64> = HashMap::new();
    for list in lists {
        for (i, id) in list.iter().enumerate() {
            *score.entry(*id).or_default() += 1.0 / (k + (i + 1) as f64);
        }
    }
    let mut out: Vec<(i64, f64)> = score.into_iter().collect();
    out.sort_by(|a, b| b.1.total_cmp(&a.1).then(a.0.cmp(&b.0)));
    out
}

/// async fn 이 들어간 trait 는 `dyn` 으로 못 쓴다. 그래서 제네릭으로 받는다.
pub struct HybridRetriever<A: Retriever, B: Retriever> {
    pub a: A,
    pub b: B,
    pub rrf_k: f64,
    /// 각 검색기에서 몇 개씩 가져와 합칠지
    pub fetch: usize,
}

impl<A: Retriever, B: Retriever> Retriever for HybridRetriever<A, B> {
    async fn search(&self, query: &str, k: usize) -> Result<Vec<Scored>> {
        let ids = |v: Vec<Scored>| v.into_iter().map(|s| s.id).collect::<Vec<_>>();
        let la = ids(self.a.search(query, self.fetch).await?);
        let lb = ids(self.b.search(query, self.fetch).await?);
        Ok(rrf(&[la, lb], self.rrf_k)
            .into_iter()
            .take(k)
            .map(|(id, score)| Scored { id, score })
            .collect())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn both_lists_beat_one_list() {
        let out = rrf(&[vec![1, 2, 3], vec![3, 4]], 60.0);
        assert_eq!(out[0].0, 3); // 두 목록에 다 나온 3이 1위
        assert!(out.iter().any(|(id, _)| *id == 4)); // 한쪽에만 나온 항목도 점수를 받는다
    }

    #[test]
