use serde::Deserialize;

use crate::db::{Db, Result};
use crate::search::Retriever;

/// 평가 파일(JSON 배열)의 한 항목.
#[derive(Debug, Clone, Deserialize)]
pub struct Question {
    pub q: String,
    /// 정답 항목 id들. 정답 없음 유형은 빈 배열.
    pub answers: Vec<i64>,
    /// 유형 태그 (direct, paraphrase, ...)
    pub tag: String,
    /// 봉인 세트 여부. 기본 eval 에서는 제외된다.
    #[serde(default)]
    pub sealed: bool,
    #[serde(default)]
    pub note: String,
}

pub fn load_questions(json: &str) -> std::result::Result<Vec<Question>, serde_json::Error> {
    serde_json::from_str(json)
}

/// 정답 id 가 DB 에 실제로 있는지 확인한다. 없는 (질문, id) 목록을 돌려준다.
pub fn missing_answers(db: &Db, qs: &[Question]) -> Result<Vec<(String, i64)>> {
    let mut missing = Vec::new();
    for q in qs {
        for &id in &q.answers {
            if db.get(id)?.is_none() {
                missing.push((q.q.clone(), id));
            }
        }
    }
    Ok(missing)
}

/// 상위 k개 안에 든 정답의 비율. 정답이 없는 질문은 None.
pub fn recall_at_k(ranked: &[i64], answers: &[i64], k: usize) -> Option<f64> {
    if answers.is_empty() {
        return None;
    }
    let hit = answers.iter().filter(|a| ranked.iter().take(k).any(|r| r == *a)).count();
    Some(hit as f64 / answers.len() as f64)
}

/// 첫 정답 순위의 역수. 못 찾으면 0, 정답이 없는 질문은 None.
pub fn reciprocal_rank(ranked: &[i64], answers: &[i64]) -> Option<f64> {
    if answers.is_empty() {
        return None;
    }
    let pos = ranked.iter().position(|r| answers.contains(r));
    Some(pos.map_or(0.0, |p| 1.0 / (p as f64 + 1.0)))
}

#[derive(Debug, Default, Clone)]
pub struct Row {
    pub n: usize,
    pub recall3: f64,
    pub recall5: f64,
    pub mrr: f64,
    /// 정답 없음 질문 중 아무것도 안 돌려준 비율 (정답 없음 질문이 없으면 None)
    pub empty_rate: Option<f64>,
}

#[derive(Debug, Default)]
pub struct Report {
    pub overall: Row,
    pub by_tag: BTreeMap<String, Row>,
}

/// 질문들의 결과를 모아서 평균을 내는 상자.
#[derive(Default)]
struct Acc {
    n: usize,
    scored: usize, // 정답이 있는 질문 수
    r3: f64,
    r5: f64,
    rr: f64,
    no_answer: usize, // 정답 없음 질문 수
    empty: usize,     // 그중 아무것도 안 돌려준 수
}

impl Acc {
    fn add(&mut self, ranked: &[i64], answers: &[i64]) {
        self.n += 1;
        match (recall_at_k(ranked, answers, 3), recall_at_k(ranked, answers, 5), reciprocal_rank(ranked, answers)) {
            (Some(a), Some(b), Some(c)) => {
                self.scored += 1;
                self.r3 += a;
                self.r5 += b;
                self.rr += c;
            }
            _ => {
                self.no_answer += 1;
                if ranked.is_empty() {
                    self.empty += 1;
                }
            }
        }
    }

    fn finish(&self) -> Row {
        let avg = |x: f64| if self.scored == 0 { 0.0 } else { x / self.scored as f64 };
        Row {
            n: self.n,
            recall3: avg(self.r3),
            recall5: avg(self.r5),
            mrr: avg(self.rr),
            empty_rate: (self.no_answer > 0).then(|| self.empty as f64 / self.no_answer as f64),
        }
    }
}

/// 질문마다 검색을 돌려 전체와 유형별 점수를 모은다.
pub async fn run_eval(retriever: &impl Retriever, qs: &[Question], include_sealed: bool) -> anyhow::Result<Report> {
    let mut overall = Acc::default();
    let mut by_tag: BTreeMap<String, Acc> = BTreeMap::new();

    for q in qs.iter().filter(|q| include_sealed || !q.sealed) {
        let ranked: Vec<i64> = retriever.search(&q.q, 5).await?.into_iter().map(|s| s.id).collect();
        overall.add(&ranked, &q.answers);
        by_tag.entry(q.tag.clone()).or_default().add(&ranked, &q.answers);
    }

    Ok(Report {
        overall: overall.finish(),
        by_tag: by_tag.into_iter().map(|(k, v)| (k, v.finish())).collect(),
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn recall_and_mrr() {
        let ranked = [7, 3, 9, 1];
        assert_eq!(recall_at_k(&ranked, &[3, 1], 3), Some(0.5));
        assert_eq!(recall_at_k(&ranked, &[3, 1], 5), Some(1.0));
        assert_eq!(reciprocal_rank(&ranked, &[9]), Some(1.0 / 3.0));
        assert_eq!(reciprocal_rank(&ranked, &[42]), Some(0.0));
        assert_eq!(recall_at_k(&ranked, &[], 3), None);
        assert_eq!(reciprocal_rank(&ranked, &[]), None);
    }

    #[test]
    fn parses_question_file() {
        let json = r#"[
            {"q": "배포는 언제 안 하기로 했지", "answers": [3], "tag": "direct"},
            {"q": "우주선 연료는", "answers": [], "tag": "no_answer", "sealed": true}
        ]"#;
        let qs = load_questions(json).unwrap();
        assert_eq!(qs.len(), 2);
        assert!(qs[1].sealed && qs[1].answers.is_empty());
    }
}

