use crate::db::Db;
use crate::error::Result;

#[derive(Debug, Clone, PartialEq)]
pub struct Scored {
    pub id: i64,
    /// 검색기마다 의미가 다르다 (FTS 는 bm25, 작을수록 좋음). 순위만 믿자.
    pub score: f64,
}

/// 질문을 받아 순위가 매겨진 결과를 돌려주는 검색기. Stage 6, 7 에서도 이걸 구현한다.
#[allow(async_fn_in_trait)]
pub trait Retriever {
    async fn search(&self, query: &str, k: usize) -> Result<Vec<Scored>>;
}

pub struct FtsRetriever<'a> {
    pub db: &'a Db,
}

/// 사용자 입력을 FTS5 MATCH 문법에 안전한 형태로 바꾼다.
/// 각 단어를 큰따옴표로 감싸고(내부의 " 는 "" 로) OR 로 잇는다. 단어가 없으면 None.
pub fn sanitize_query(input: &str) -> Option<String> {
    let tokens: Vec<String> = input
        .split_whitespace()
        .map(|t| t.replace('"', r#""""#))
        .filter(|t| !t.is_empty())
        .map(|t| format!(r#""{t}""#))
        .collect();
    if tokens.is_empty() { None } else { Some(tokens.join(" OR ")) }
}

impl Retriever for FtsRetriever<'_> {
    async fn search(&self, query: &str, k: usize) -> Result<Vec<Scored>> {
        let Some(q) = sanitize_query(query) else {
            return Ok(vec![]);
        };
        let mut stmt = self.db.conn().prepare(
            "SELECT items.id, bm25(items_fts)
             FROM items_fts JOIN items ON items.id = items_fts.rowid
             WHERE items_fts MATCH ?1 AND items.status = 'active'
             ORDER BY bm25(items_fts)
             LIMIT ?2",
        )?;
        let rows = stmt.query_map(rusqlite::params![q, k as i64], |r| {
            Ok(Scored { id: r.get(0)?, score: r.get(1)? })
        })?;
        Ok(rows.collect::<std::result::Result<Vec<_>, _>>()?)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::item::{Kind, NewItem};

    fn add(db: &Db, body: &str) -> i64 {
        db.insert(&NewItem { kind: Kind::Work, scope: "global".into(), body: body.into(), why: None, source: "t".into() }).unwrap()
    }

    #[test]
    fn sanitize_handles_special_chars() {
        assert_eq!(sanitize_query("a-b c:d").unwrap(), r#""a-b" OR "c:d""#);
        assert_eq!(sanitize_query(r#"say "hi""#).unwrap(), r#""say" OR """hi""""#);
        assert_eq!(sanitize_query("   "), None);
    }

    #[tokio::test]
    async fn finds_active_only() {
        let db = Db::open_in_memory().unwrap();
        let a = add(&db, "deploy on friday is banned");
        let b = add(&db, "deploy with docker");
        db.conn().execute("UPDATE items SET status = 'superseded' WHERE id = ?1", [b]).unwrap();
        let r = FtsRetriever { db: &db };
        let ids: Vec<i64> = r.search("deploy", 5).await.unwrap().into_iter().map(|s| s.id).collect();
        assert_eq!(ids, vec![a]);
    }

    #[tokio::test]
    async fn weird_input_does_not_error() {
        let db = Db::open_in_memory().unwrap();
        add(&db, "hello world");
        let r = FtsRetriever { db: &db };
        for q in [r#"""#, "a:b", "-x", "(", "AND OR", "한글 검색어"] {
            assert!(r.search(q, 3).await.is_ok(), "{q}");
        }
    }

    #[tokio::test]
    async fn index_follows_updates() {
        let db = Db::open_in_memory().unwrap();
        let id = add(&db, "old text");
        db.conn().execute("UPDATE items SET body = 'new text' WHERE id = ?1", [id]).unwrap();
        let r = FtsRetriever { db: &db };
        assert!(r.search("old", 3).await.unwrap().is_empty());
        assert_eq!(r.search("new", 3).await.unwrap().len(), 1);
    }
}

