//! 기억 관리: 중복 후보, 충돌 후보, 오래된 항목.
//! 어느 것도 자동으로 고치지 않는다. 후보를 보여 주고 판단은 사람이 한다.

use crate::db::{Db, now_secs};
use crate::embed::Embedder;
use crate::error::Result;
use crate::item::{Item, Kind};
use crate::vector::{cosine, load_vectors, top_k_heap};

/// 이 이상이면 '같은 말을 두 번' 했을 가능성이 크다 (중복 후보).
pub const DUPLICATE_THRESHOLD: f32 = 0.9;
/// 이 이상이면서 중복 기준보다 낮으면 '비슷한 주제에 다른 말' 후보 (충돌 후보).
pub const CONFLICT_THRESHOLD: f32 = 0.6;

/// 새로 넣으려는 글과 비슷한 active 항목을 유사도 내림차순으로 돌려준다.
pub async fn similar_to(
    db: &Db,
    embedder: &impl Embedder,
    text: &str,
    min: f32,
) -> Result<Vec<(i64, f32)>> {
    let q = embedder.embed(&[text.to_string()]).await?.remove(0);
    let all = load_vectors(db, embedder.model_id())?;
    let scored = all
        .iter()
        .map(|(id, v)| (*id, cosine(&q, v)))
        .filter(|(_, s)| *s >= min);
    Ok(top_k_heap(scored, 5))
}

/// 같은 scope 안에서 유사도가 [lo, hi) 인 active 항목 쌍. 충돌 후보 목록.
pub fn similar_pairs(db: &Db, model: &str, lo: f32, hi: f32) -> Result<Vec<(i64, i64, f32)>> {
    let vectors = load_vectors(db, model)?;
    let mut with_scope = Vec::new();
    for (id, v) in vectors {
        if let Some(it) = db.get(id)? {
            with_scope.push((it.scope, id, v));
        }
    }
    let mut out = Vec::new();
    for (i, (scope_a, a, va)) in with_scope.iter().enumerate() {
        for (scope_b, b, vb) in &with_scope[i + 1..] {
            if scope_a != scope_b {
                continue;
            }
            let s = cosine(va, vb);
            if s >= lo && s < hi {
                out.push((*a.min(b), *a.max(b), s));
            }
        }
    }
    out.sort_by(|x, y| y.2.total_cmp(&x.2));
    Ok(out)
}

/// 종류마다 '오래됐다'고 볼 기간(일). 프로젝트 맥락은 빨리 낡고 선호는 오래 간다.
pub fn stale_after_days(kind: Kind) -> i64 {
    match kind {
        Kind::Project => 90,
        Kind::Work => 180,
        Kind::Pref => 365,
    }
}

/// 마지막 확인(없으면 생성) 이후 기간이 지난 active 항목.
pub fn stale_items(db: &Db, now: i64) -> Result<Vec<Item>> {
    let mut stmt = db.conn().prepare(
        "SELECT id, kind, COALESCE(checked_at, created_at) FROM items
         WHERE status = 'active' ORDER BY id",
    )?;
    let rows = stmt
        .query_map([], |r| {
            Ok((
                r.get::<_, i64>(0)?,
                r.get::<_, Kind>(1)?,
                r.get::<_, i64>(2)?,
            ))
        })?
        .collect::<rusqlite::Result<Vec<_>>>()?;
    let mut out = Vec::new();
    for (id, kind, last) in rows {
        if now - last > stale_after_days(kind) * 86_400
            && let Some(it) = db.get(id)?
        {
            out.push(it);
        }
    }
    Ok(out)
}

/// 지금 기준의 오래된 항목.
pub fn stale_now(db: &Db) -> Result<Vec<Item>> {
    stale_items(db, now_secs())
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::embed::{FakeEmbedder, embed_missing};
    use crate::item::NewItem;

    fn add(db: &Db, kind: Kind, scope: &str, body: &str) -> i64 {
        db.insert(&NewItem {
            kind,
            scope: scope.into(),
            body: body.into(),
            why: None,
            source: "t".into(),
        })
        .unwrap()
    }

    #[tokio::test]
    async fn finds_duplicate_candidate() {
        let db = Db::open_in_memory().unwrap();
        let a = add(&db, Kind::Work, "global", "deploy on friday is banned");
        add(&db, Kind::Work, "global", "use sqlite for storage");
        let e = FakeEmbedder { dim: 256 };
        embed_missing(&db, &e, 10).await.unwrap();
        let hits = similar_to(&db, &e, "deploy on friday is banned!", DUPLICATE_THRESHOLD)
            .await
            .unwrap();
        assert_eq!(hits.len(), 1);
        assert_eq!(hits[0].0, a);
    }

    #[tokio::test]
    async fn pairs_stay_within_scope() {
        let db = Db::open_in_memory().unwrap();
        let a = add(&db, Kind::Project, "projA", "state management with signals");
        let b = add(&db, Kind::Project, "projA", "state management with redux");
        add(&db, Kind::Project, "projB", "state management with signals");
        let e = FakeEmbedder { dim: 256 };
        embed_missing(&db, &e, 10).await.unwrap();
        let pairs = similar_pairs(&db, e.model_id(), CONFLICT_THRESHOLD, 0.99).unwrap();
        assert_eq!(pairs.len(), 1);
        assert_eq!((pairs[0].0, pairs[0].1), (a, b));
    }

    #[test]
    fn stale_depends_on_kind_and_confirm() {
        let db = Db::open_in_memory().unwrap();
        let p = add(&db, Kind::Project, "projA", "old project fact");
        let pref = add(&db, Kind::Pref, "global", "old preference");
        let now = now_secs() + 100 * 86_400; // 100일 뒤
        let ids: Vec<i64> = stale_items(&db, now)
            .unwrap()
            .iter()
            .map(|i| i.id)
            .collect();
        assert_eq!(ids, vec![p]); // 선호는 아직 오래되지 않았다
        assert!(!ids.contains(&pref));

        db.confirm(p).unwrap();
        assert!(stale_items(&db, now_secs() + 10).unwrap().is_empty());
    }
}

