use std::fs;
use std::path::PathBuf;

use anyhow::{Context, Result, bail};
use clap::{Parser, Subcommand, ValueEnum};
use mnemo_core::embed::{Embedder, FakeEmbedder, HttpEmbedder, embed_missing};
use mnemo_core::hybrid::HybridRetriever;
use mnemo_core::search::{FtsRetriever, Retriever, Scored};
use mnemo_core::vector::VectorRetriever;
use mnemo_core::{Db, Item, Kind, NewItem, Status, eval, import};

#[derive(Parser)]
#[command(version, about = "내 지식 DB")]
struct Cli {
    /// DB 파일 경로 (옵션 > MNEMO_DB 환경변수 > ./mnemo.db)
    #[arg(long, env = "MNEMO_DB", default_value = "mnemo.db", global = true)]
    db: PathBuf,

    #[command(subcommand)]
    cmd: Cmd,
}

// MNEMO_EMBED_URL 이 있으면 실제 제공자, 없으면 가짜 임베더
enum AnyEmbedder {
    Fake(FakeEmbedder),
    Http(HttpEmbedder),
}

impl AnyEmbedder {
    fn from_env() -> Result<Self> {
        if std::env::var_os("MNEMO_EMBED_URL").is_some() {
            Ok(Self::Http(HttpEmbedder::from_env()?))
        } else {
            Ok(Self::Fake(FakeEmbedder { dim: 128 }))
        }
    }
}

impl Embedder for AnyEmbedder {
    fn model_id(&self) -> &str {
        match self {
            Self::Fake(e) => e.model_id(),
            Self::Http(e) => e.model_id(),
        }
    }
    fn dim(&self) -> usize {
        match self {
            Self::Fake(e) => e.dim(),
            Self::Http(e) => e.dim(),
        }
    }
    async fn embed(&self, texts: &[String]) -> mnemo_core::Result<Vec<Vec<f32>>> {
        match self {
            Self::Fake(e) => e.embed(texts).await,
            Self::Http(e) => e.embed(texts).await,
        }
    }
}

#[derive(Clone, Copy, ValueEnum)]
enum Mode {
    Fts,
    Vector,
    Hybrid,
}

/// 모드에 맞는 검색을 돌린다. async fn 이 든 trait 는 `dyn` 으로 못 쓰니 match 로 갈라낸다.
async fn run_search(db: &Db, mode: Mode, q: &str, k: usize) -> Result<Vec<Scored>> {
    let emb = AnyEmbedder::from_env()?;
    Ok(match mode {
        Mode::Fts => FtsRetriever { db }.search(q, k).await?,
        Mode::Vector => VectorRetriever { db, embedder: &emb }.search(q, k).await?,
        Mode::Hybrid => {
            let h = HybridRetriever {
                a: FtsRetriever { db },
                b: VectorRetriever { db, embedder: &emb },
                rrf_k: 60.0,
                fetch: 20,
            };
            h.search(q, k).await?
        }
    })
}

#[derive(Subcommand)]
enum Cmd {
    /// 항목 하나 추가
    Add {
        /// project / pref / work
        kind: Kind,
        /// 프로젝트 이름 또는 global
        scope: String,
        /// 본문 (사실 하나)
        body: String,
        /// 이유
        #[arg(long)]
        why: Option<String>,
    },
    /// 항목 목록
    List {
        #[arg(long)]
        kind: Option<Kind>,
        #[arg(long)]
        scope: Option<String>,
        #[arg(long, default_value = "active")]
        status: Status,
    },
    /// 항목 하나를 자세히
    Get { id: i64 },
    /// 텍스트 파일에서 한 줄에 하나씩 가져오기
    Import { file: PathBuf },
    /// 평가 파일의 정답 id가 DB에 다 있는지 확인
    EvalCheck { file: PathBuf },
    /// 질문으로 검색
    Search {
        query: String,
        #[arg(long, value_enum, default_value = "fts")]
        mode: Mode,
        #[arg(short, default_value_t = 5)]
        k: usize,
    },
    /// 평가 세트로 점수 내기 (봉인 문항은 기본 제외)
    Eval {
        #[arg(default_value = "eval.json")]
        file: PathBuf,
        #[arg(long, value_enum, default_value = "fts")]
        mode: Mode,
        /// 봉인 문항도 포함 (Stage 7 마지막에 딱 한 번만!)
        #[arg(long)]
        include_sealed: bool,
    },
    /// 아직 임베딩이 없는 항목을 임베딩
    Embed,
}

#[tokio::main]
async fn main() -> Result<()> {
    let cli = Cli::parse();
    let db = Db::open(&cli.db).with_context(|| format!("{} 을 열지 못했어요", cli.db.display()))?;

    match cli.cmd {
        Cmd::Add { kind, scope, body, why } => {
            let id = db.insert(&NewItem { kind, scope, body, why, source: "manual".into() })?;
            println!("추가됨: #{id}");
        }
        Cmd::List { kind, scope, status } => {
            for it in db.list(kind, scope.as_deref(), status)? {
                println!("#{:<4} [{}/{}] {}", it.id, it.kind.as_str(), it.scope, it.body);
            }
        }
        Cmd::Get { id } => match db.get(id)? {
            Some(it) => print_item(&it),
            None => bail!("#{id} 항목이 없어요"),
        },
        Cmd::Import { file } => {
            let text = fs::read_to_string(&file)
                .with_context(|| format!("{} 을 읽지 못했어요", file.display()))?;
            match import::parse_lines(&text) {
                Ok(items) => {
                    let n = db.insert_many(&items)?;
                    println!("{n}개를 가져왔어요");
                }
                Err(errors) => {
                    for (line, msg) in &errors {
                        eprintln!("{}:{line}: {msg}", file.display());
                    }
                    bail!("{}줄에 문제가 있어서 아무것도 넣지 않았어요", errors.len());
                }
            }
        }
        Cmd::EvalCheck { file } => {
            let text = fs::read_to_string(&file)
                .with_context(|| format!("{} 을 읽지 못했어요", file.display()))?;
            let qs = eval::load_questions(&text)?;
            let missing = eval::missing_answers(&db, &qs)?;
            for (q, id) in &missing {
                eprintln!("정답 id #{id} 가 DB에 없어요: {q}");
            }
            if !missing.is_empty() {
                bail!("{}건의 정답 id를 고치세요", missing.len());
            }
            let sealed = qs.iter().filter(|q| q.sealed).count();
            println!("질문 {}개 (봉인 {}개), 정답 id 모두 확인됨", qs.len(), sealed);
        }
        Cmd::Search { query, mode, k } => {
            for (i, hit) in run_search(&db, mode, &query, k).await?.iter().enumerate() {
                if let Some(it) = db.get(hit.id)? {
                    println!("{:>2}) [{}/{}] {}  ({:.2})", i + 1, it.kind.as_str(), it.scope, it.body, hit.score);
                }
            }
        }
        Cmd::Eval { file, mode, include_sealed } => {
            let text = fs::read_to_string(&file)
                .with_context(|| format!("{} 을 읽지 못했어요", file.display()))?;
            let qs = eval::load_questions(&text)?;
            let emb = AnyEmbedder::from_env()?;
            let report = match mode {
                Mode::Fts => eval::run_eval(&FtsRetriever { db: &db }, &qs, include_sealed).await?,
                Mode::Vector => eval::run_eval(&VectorRetriever { db: &db, embedder: &emb }, &qs, include_sealed).await?,
                Mode::Hybrid => {
                    let h = HybridRetriever {
                        a: FtsRetriever { db: &db },
                        b: VectorRetriever { db: &db, embedder: &emb },
                        rrf_k: 60.0,
                        fetch: 20,
                    };
                    eval::run_eval(&h, &qs, include_sealed).await?
                }
            };

            println!("{:<14} {:>3} {:>9} {:>9} {:>7}", "유형", "n", "Recall@3", "Recall@5", "MRR");
            let line = |name: &str, r: &eval::Row| {
                println!("{:<14} {:>3} {:>9.2} {:>9.2} {:>7.2}", name, r.n, r.recall3, r.recall5, r.mrr);
                if let Some(e) = r.empty_rate {
                    println!("{:<14}     (정답 없음 중 빈 결과 비율 {:.2})", "", e);
                }
            };
            line("전체", &report.overall);
            for (tag, row) in &report.by_tag {
                line(tag, row);
            }
        }
        Cmd::Embed => {
            let n = embed_missing(&db, &AnyEmbedder::from_env()?, 32).await?;
            println!("{n}개를 임베딩했어요");
        }
    }
    Ok(())
}

fn print_item(it: &Item) {
    println!("id         {}", it.id);
    println!("kind       {}", it.kind.as_str());
    println!("scope      {}", it.scope);
    println!("body       {}", it.body);
    println!("why        {}", it.why.as_deref().unwrap_or("-"));
    println!("source     {}", it.source);
    println!("status     {}", it.status.as_str());
    println!("created_at {} (UTC 초)", it.created_at);
}

