        tokenize = 'unicode61'
    );
    CREATE TRIGGER items_ai AFTER INSERT ON items BEGIN
        INSERT INTO items_fts(rowid, body, why) VALUES (new.id, new.body, new.why);
    END;
    CREATE TRIGGER items_ad AFTER DELETE ON items BEGIN
        INSERT INTO items_fts(items_fts, rowid, body, why) VALUES ('delete', old.id, old.body, old.why);
    END;
    CREATE TRIGGER items_au AFTER UPDATE ON items BEGIN
        INSERT INTO items_fts(items_fts, rowid, body, why) VALUES ('delete', old.id, old.body, old.why);
        INSERT INTO items_fts(rowid, body, why) VALUES (new.id, new.body, new.why);
    END;
    INSERT INTO items_fts(items_fts) VALUES ('rebuild');
"#,
// v3: 임베딩. 본문이 바뀌면 그 항목의 벡터는 무효 -> 트리거로 지운다
r#"
    CREATE TABLE embeddings (
        item_id    INTEGER NOT NULL REFERENCES items(id),
        model      TEXT NOT NULL,
        dim        INTEGER NOT NULL,
        vec        BLOB NOT NULL,
        created_at INTEGER NOT NULL,
        PRIMARY KEY (item_id, model)
    );
    CREATE TRIGGER items_body_changed AFTER UPDATE OF body ON items BEGIN
        DELETE FROM embeddings WHERE item_id = new.id;
    END;
"#,
// v4: 감사 로그와 '마지막으로 확인한 시각'. 삽입 기록은 어떤 경로로 넣어도 남도록 트리거로 남긴다
r#"
    CREATE TABLE audit_log (
        id      INTEGER PRIMARY KEY AUTOINCREMENT,
        item_id INTEGER,
        action  TEXT NOT NULL,     -- insert / supersede / confirm ...
        actor   TEXT NOT NULL,     -- human / ai / import
        at      INTEGER NOT NULL,  -- UTC 초
        detail  TEXT
    );
    ALTER TABLE items ADD COLUMN checked_at INTEGER;
    CREATE TRIGGER items_audit_insert AFTER INSERT ON items BEGIN
        INSERT INTO audit_log (item_id, action, actor, at, detail)
        VALUES (
            new.id, 'insert',
            CASE new.source WHEN 'manual' THEN 'human' WHEN 'import' THEN 'import' WHEN 'ai' THEN 'ai' ELSE new.source END,
            new.created_at, new.kind || ':' || new.scope
        );
    END;
"#,
// v5: AI 가 제안한 후보는 여기에만 들어간다. items 로 가는 길은 사람의 승인뿐
r#"
    CREATE TABLE pending (
        id          INTEGER PRIMARY KEY AUTOINCREMENT,
        kind        TEXT NOT NULL,
        scope       TEXT NOT NULL,
        body        TEXT NOT NULL,
        why         TEXT,
        source_ref  TEXT,                      -- 어느 파일/대화의 어디에서 나왔는지
        proposed_at INTEGER NOT NULL,
        state       TEXT NOT NULL DEFAULT 'waiting'   -- waiting / approved / rejected
    );
    CREATE TABLE llm_usage (
        id            INTEGER PRIMARY KEY AUTOINCREMENT,
        at            INTEGER NOT NULL,
        model         TEXT NOT NULL,
        input_tokens  INTEGER NOT NULL,
        output_tokens INTEGER NOT NULL
    );
"#];

pub struct Db {
    conn: Connection,
}

impl Db {
    pub fn open(path: &Path) -> Result<Self> {
        Self::init(Connection::open(path)?)
    }

    pub fn open_in_memory() -> Result<Self> {
        Self::init(Connection::open_in_memory()?)
    }

    fn init(conn: Connection) -> Result<Self> {
        conn.pragma_update(None, "foreign_keys", true)?;
        let db = Self { conn };
        db.migrate()?;
        Ok(db)
    }

    pub fn conn(&self) -> &Connection {
        &self.conn
    }

    pub fn user_version(&self) -> Result<i64> {
        Ok(self.conn.query_row("PRAGMA user_version", [], |r| r.get(0))?)
    }

    fn migrate(&self) -> Result<()> {
        let current = self.user_version()? as usize;
        for (i, sql) in MIGRATIONS.iter().enumerate().skip(current) {
            // 마이그레이션 하나는 트랜잭션 하나. 중간에 실패하면 버전도 안 오른다.
            let tx = self.conn.unchecked_transaction()?;
            tx.execute_batch(sql)?;
            tx.pragma_update(None, "user_version", (i + 1) as i64)?;
            tx.commit()?;
        }
        Ok(())
    }

    pub fn insert(&self, new: &NewItem) -> Result<i64> {
        self.conn.execute(
            "INSERT INTO items (kind, scope, body, why, source, created_at)
             VALUES (?1, ?2, ?3, ?4, ?5, ?6)",
            params![new.kind, new.scope, new.body, new.why, new.source, now_secs()],
        )?;
        Ok(self.conn.last_insert_rowid())
    }

    /// 전부 넣거나 전부 취소한다 (트랜잭션 하나).
    pub fn insert_many(&self, items: &[NewItem]) -> Result<usize> {
        let tx = self.conn.unchecked_transaction()?;
        for it in items {
            self.insert(it)?;
        }
        tx.commit()?;
        Ok(items.len())
    }

    /// old 를 superseded 로 바꾸고, new 를 넣고, 둘을 연결한다. 전부 한 트랜잭션.
    pub fn supersede(&self, old_id: i64, new: &NewItem) -> Result<i64> {
        let tx = self.conn.unchecked_transaction()?;
        let old = self.get(old_id)?.ok_or(Error::NotFound(old_id))?;
        if old.status != Status::Active {
            return Err(Error::Invalid(format!("#{old_id} 는 active 가 아니라서 대체할 수 없어요")));
        }
        let new_id = self.insert(new)?;
        tx.execute("UPDATE items SET supersedes_id = ?1 WHERE id = ?2", params![old_id, new_id])?;
        tx.execute("UPDATE items SET status = ?1 WHERE id = ?2", params![Status::Superseded, old_id])?;
        self.audit(old_id, "supersede", "human", Some(&format!("#{new_id} 로 대체")))?;
        tx.commit()?;
        Ok(new_id)
    }

    /// 항목이 아직 맞다고 사람이 확인했다. '오래된 항목' 목록에서 빠진다.
    pub fn confirm(&self, id: i64) -> Result<()> {
        let tx = self.conn.unchecked_transaction()?;
        let n = tx.execute(
            "UPDATE items SET checked_at = ?1 WHERE id = ?2 AND status = 'active'",
            params![now_secs(), id],
        )?;
        if n == 0 {
            return Err(Error::NotFound(id));
        }
        self.audit(id, "confirm", "human", None)?;
        tx.commit()?;
        Ok(())
    }

    fn audit(&self, item_id: i64, action: &str, actor: &str, detail: Option<&str>) -> Result<()> {
        self.conn.execute(
            "INSERT INTO audit_log (item_id, action, actor, at, detail) VALUES (?1, ?2, ?3, ?4, ?5)",
            params![item_id, action, actor, now_secs(), detail],
        )?;
        Ok(())
    }

    pub fn get(&self, id: i64) -> Result<Option<Item>> {
        let mut stmt = self.conn.prepare(
            "SELECT id, kind, scope, body, why, source, created_at, status, supersedes_id
             FROM items WHERE id = ?1",
        )?;
        let mut rows = stmt.query_map([id], row_to_item)?;
        Ok(rows.next().transpose()?)
    }

    pub fn list(&self, kind: Option<Kind>, scope: Option<&str>, status: Status) -> Result<Vec<Item>> {
        let mut stmt = self.conn.prepare(
            "SELECT id, kind, scope, body, why, source, created_at, status, supersedes_id
             FROM items
             WHERE status = ?1
               AND (?2 IS NULL OR kind = ?2)
               AND (?3 IS NULL OR scope = ?3)
             ORDER BY id",
        )?;
        Ok(stmt
            .query_map(params![status, kind, scope], row_to_item)?
            .collect::<rusqlite::Result<Vec<_>>>()?)
    }
}

fn row_to_item(r: &Row<'_>) -> rusqlite::Result<Item> {
    Ok(Item {
        id: r.get(0)?,
        kind: r.get(1)?,
        scope: r.get(2)?,
        body: r.get(3)?,
        why: r.get(4)?,
        source: r.get(5)?,
        created_at: r.get(6)?,
        status: r.get(7)?,
        supersedes_id: r.get(8)?,
    })
}

pub fn now_secs() -> i64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn sample(kind: Kind, scope: &str, body: &str) -> NewItem {
