    }

    #[test]
    fn list_filters() {
        let db = Db::open_in_memory().unwrap();
        db.insert(&sample(Kind::Project, "projA", "a")).unwrap();
        db.insert(&sample(Kind::Pref, "global", "b")).unwrap();
        assert_eq!(db.list(None, None, Status::Active).unwrap().len(), 2);
        assert_eq!(db.list(Some(Kind::Pref), None, Status::Active).unwrap().len(), 1);
        assert_eq!(db.list(None, Some("projA"), Status::Active).unwrap().len(), 1);
        assert_eq!(db.list(None, None, Status::Archived).unwrap().len(), 0);
    }

    #[test]
    fn migration_is_idempotent() {
        let path = std::env::temp_dir().join(format!("mnemo-test-{}", std::process::id()));
        let _ = std::fs::remove_file(&path);
        let db = Db::open(&path).unwrap();
        assert_eq!(db.user_version().unwrap(), MIGRATIONS.len() as i64);
        drop(db);
        let db = Db::open(&path).unwrap(); // 다시 열어도 에러 없이 같은 버전
        assert_eq!(db.user_version().unwrap(), MIGRATIONS.len() as i64);
        let _ = std::fs::remove_file(&path);
    }

    fn count(db: &Db, table: &str) -> i64 {
        db.conn()
            .query_row(&format!("SELECT COUNT(*) FROM {table}"), [], |r| r.get(0))
            .unwrap()
    }

    #[test]
    fn supersede_links_and_audits() {
        let db = Db::open_in_memory().unwrap();
        let old = db.insert(&sample(Kind::Project, "projA", "상태 관리는 A")).unwrap();
        let new = db.supersede(old, &sample(Kind::Project, "projA", "상태 관리는 B")).unwrap();
        assert_eq!(db.get(old).unwrap().unwrap().status, Status::Superseded);
        assert_eq!(db.get(new).unwrap().unwrap().supersedes_id, Some(old));
        assert_eq!(count(&db, "audit_log"), 3); // insert, insert, supersede
        assert!(db.supersede(old, &sample(Kind::Project, "projA", "C")).is_err());
        assert!(matches!(db.supersede(999, &sample(Kind::Work, "g", "x")), Err(Error::NotFound(999))));
    }

    #[test]
    fn supersede_rolls_back_when_second_write_fails() {
        let db = Db::open_in_memory().unwrap();
        let old = db.insert(&sample(Kind::Project, "projA", "a")).unwrap();
        // 상태 변경(두 번째 쓰기)이 반드시 실패하게 만든다
        db.conn()
            .execute_batch(
                "CREATE TRIGGER no_status_change BEFORE UPDATE OF status ON items
                 BEGIN SELECT RAISE(ABORT, 'boom'); END;",
            )
            .unwrap();
        assert!(db.supersede(old, &sample(Kind::Project, "projA", "b")).is_err());
        assert_eq!(count(&db, "items"), 1); // 새 항목이 남지 않았다
        assert_eq!(count(&db, "audit_log"), 1);
        assert_eq!(db.get(old).unwrap().unwrap().status, Status::Active);
    }

    #[test]
    fn confirm_marks_checked() {
        let db = Db::open_in_memory().unwrap();
        let id = db.insert(&sample(Kind::Work, "global", "x")).unwrap();
        db.confirm(id).unwrap();
        let checked: Option<i64> = db
            .conn()
            .query_row("SELECT checked_at FROM items WHERE id = ?1", [id], |r| r.get(0))
            .unwrap();
        assert!(checked.is_some());
        assert!(db.confirm(999).is_err());
    }

    #[test]
    fn unknown_status_is_an_error_not_a_panic() {
        let db = Db::open_in_memory().unwrap();
        let id = db.insert(&sample(Kind::Work, "global", "x")).unwrap();
        db.conn().execute("UPDATE items SET status = 'weird' WHERE id = ?1", [id]).unwrap();
        assert!(db.get(id).is_err());
    }
}

//! 승인 큐. AI 가 제안한 후보는 `pending` 에만 쌓이고,
//! 사람이 승인한 것만 `items` 로 옮겨진다 (출처는 "ai").

use rusqlite::params;

use crate::db::{Db, now_secs};
use crate::error::{Error, Result};
use crate::item::{Kind, NewItem};

/// 후보 하나 (LLM 출력을 검증한 뒤의 모양).
#[derive(Debug, Clone, PartialEq)]
pub struct Candidate {
    pub kind: Kind,
    pub scope: String,
    pub body: String,
    pub why: Option<String>,
}

#[derive(Debug, Clone)]
pub struct Pending {
    pub id: i64,
    pub candidate: Candidate,
    pub source_ref: Option<String>,
    pub proposed_at: i64,
}

pub fn add_pending(db: &Db, c: &Candidate, source_ref: Option<&str>) -> Result<i64> {
    db.conn().execute(
        "INSERT INTO pending (kind, scope, body, why, source_ref, proposed_at)
         VALUES (?1, ?2, ?3, ?4, ?5, ?6)",
        params![c.kind, c.scope, c.body, c.why, source_ref, now_secs()],
    )?;
    Ok(db.conn().last_insert_rowid())
}

/// 대기 중인 후보를 오래된 것부터.
pub fn waiting(db: &Db) -> Result<Vec<Pending>> {
    let mut stmt = db.conn().prepare(
        "SELECT id, kind, scope, body, why, source_ref, proposed_at
         FROM pending WHERE state = 'waiting' ORDER BY id",
    )?;
    let rows = stmt.query_map([], |r| {
        Ok(Pending {
            id: r.get(0)?,
            candidate: Candidate {
                kind: r.get(1)?,
                scope: r.get(2)?,
                body: r.get(3)?,
                why: r.get(4)?,
            },
            source_ref: r.get(5)?,
            proposed_at: r.get(6)?,
        })
    })?;
    Ok(rows.collect::<rusqlite::Result<Vec<_>>>()?)
}

/// 승인: (고친 내용이 있으면 그걸로) items 에 넣고 후보를 approved 로. 한 트랜잭션.
pub fn approve(db: &Db, id: i64, edited: Option<&Candidate>) -> Result<i64> {
    let tx = db.conn().unchecked_transaction()?;
    let p = waiting(db)?
        .into_iter()
        .find(|p| p.id == id)
        .ok_or(Error::NotFound(id))?;
    let c = edited.unwrap_or(&p.candidate);
    let item_id = db.insert(&NewItem {
        kind: c.kind,
        scope: c.scope.clone(),
        body: c.body.clone(),
        why: c.why.clone(),
        source: "ai".into(),
    })?;
    tx.execute("UPDATE pending SET state = 'approved' WHERE id = ?1", [id])?;
    tx.commit()?;
    Ok(item_id)
}

pub fn reject(db: &Db, id: i64) -> Result<()> {
    let n = db.conn().execute(
        "UPDATE pending SET state = 'rejected' WHERE id = ?1 AND state = 'waiting'",
        [id],
    )?;
    if n == 0 {
        return Err(Error::NotFound(id));
    }
    Ok(())
}

/// LLM 호출 한 번의 토큰 사용량을 남긴다 (비용 추정용).
pub fn record_usage(db: &Db, model: &str, input_tokens: u64, output_tokens: u64) -> Result<()> {
    db.conn().execute(
        "INSERT INTO llm_usage (at, model, input_tokens, output_tokens) VALUES (?1, ?2, ?3, ?4)",
        params![now_secs(), model, input_tokens as i64, output_tokens as i64],
    )?;
    Ok(())
}

/// (호출 횟수, 입력 토큰 합, 출력 토큰 합)
pub fn usage_total(db: &Db) -> Result<(i64, i64, i64)> {
    Ok(db.conn().query_row(
        "SELECT COUNT(*), COALESCE(SUM(input_tokens), 0), COALESCE(SUM(output_tokens), 0) FROM llm_usage",
        [],
        |r| Ok((r.get(0)?, r.get(1)?, r.get(2)?)),
    )?)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::item::Status;

    fn cand(body: &str) -> Candidate {
        Candidate {
            kind: Kind::Pref,
            scope: "global".into(),
            body: body.into(),
            why: None,
        }
    }

    fn item_count(db: &Db) -> usize {
