    }

    #[test]
    fn only_approved_candidates_reach_items() {
        let db = Db::open_in_memory().unwrap();
        let a = add_pending(&db, &cand("keep functions small"), Some("notes.txt")).unwrap();
        let b = add_pending(&db, &cand("ignore this one"), None).unwrap();
        assert_eq!(item_count(&db), 0); // 제안만으로는 아무것도 저장되지 않는다

        let item = approve(&db, a, None).unwrap();
