// MNEMO_EMBED_URL 이 있으면 실제 제공자, 없으면 가짜 임베더
enum AnyEmbedder {
    Fake(FakeEmbedder),
    Http(HttpEmbedder),
}

impl AnyEmbedder {
    fn from_env() -> Result<Self> {
        if std::env::var_os("MNEMO_EMBED_URL").is_some() {
            Ok(Self::Http(HttpEmbedder::from_env()?))
        } else {
            Ok(Self::Fake(FakeEmbedder { dim: 128 }))
        }
    }
}

impl Embedder for AnyEmbedder {
    fn model_id(&self) -> &str {
        match self {
            Self::Fake(e) => e.model_id(),
            Self::Http(e) => e.model_id(),
        }
    }
    fn dim(&self) -> usize {
        match self {
            Self::Fake(e) => e.dim(),
            Self::Http(e) => e.dim(),
        }
    }
    async fn embed(&self, texts: &[String]) -> mnemo_core::Result<Vec<Vec<f32>>> {
        match self {
            Self::Fake(e) => e.embed(texts).await,
            Self::Http(e) => e.embed(texts).await,
        }
    }
}

#[derive(Clone, Copy, ValueEnum)]
enum Mode {
    Fts,
    Vector,
    Hybrid,
}

/// 모드에 맞는 검색을 돌린다. async fn 이 든 trait 는 `dyn` 으로 못 쓰니 match 로 갈라낸다.
async fn run_search(db: &Db, mode: Mode, q: &str, k: usize) -> Result<Vec<Scored>> {
    let emb = AnyEmbedder::from_env()?;
    Ok(match mode {
        Mode::Fts => FtsRetriever { db }.search(q, k).await?,
        Mode::Vector => VectorRetriever { db, embedder: &emb }.search(q, k).await?,
        Mode::Hybrid => {
            let h = HybridRetriever {
                a: FtsRetriever { db },
                b: VectorRetriever { db, embedder: &emb },
                rrf_k: 60.0,
                fetch: 20,
            };
            h.search(q, k).await?
        }
    })
}

#[derive(Subcommand)]
enum Cmd {
    /// 항목 하나 추가
    Add {
        /// project / pref / work
        kind: Kind,
        /// 프로젝트 이름 또는 global
        scope: String,
        /// 본문 (사실 하나)
        body: String,
        /// 이유
        #[arg(long)]
        why: Option<String>,
        /// 중복 후보가 있어도 묻지 않고 새로 넣기
        #[arg(long)]
        force: bool,
    },
    /// 항목을 새 내용으로 대체 (옛 항목은 superseded 가 된다)
    Supersede {
        old_id: i64,
        /// 새 본문
        body: String,
        #[arg(long)]
        why: Option<String>,
    },
    /// 항목이 아직 맞다고 확인 (오래된 항목 목록에서 빠진다)
    Confirm { id: i64 },
    /// 오랫동안 확인하지 않은 active 항목
    Stale,
    /// 같은 범위에서 비슷하지만 다른 말을 하는 항목 쌍 (판단은 사람이)
    Conflicts,
    /// 항목 목록
    List {
        #[arg(long)]
        kind: Option<Kind>,
        #[arg(long)]
        scope: Option<String>,
        #[arg(long, default_value = "active")]
        status: Status,
    },
    /// 항목 하나를 자세히
    Get { id: i64 },
    /// 텍스트 파일에서 한 줄에 하나씩 가져오기
    Import { file: PathBuf },
    /// 평가 파일의 정답 id가 DB에 다 있는지 확인
    EvalCheck { file: PathBuf },
    /// 질문으로 검색
    Search {
        query: String,
        #[arg(long, value_enum, default_value = "fts")]
        mode: Mode,
        #[arg(short, default_value_t = 5)]
        k: usize,
        /// 대체·보관된 항목까지 (키워드 검색만)
        #[arg(long)]
        history: bool,
    },
    /// 평가 세트로 점수 내기 (봉인 문항은 기본 제외)
    Eval {
        #[arg(default_value = "eval.json")]
        file: PathBuf,
        #[arg(long, value_enum, default_value = "fts")]
        mode: Mode,
        /// 봉인 문항도 포함 (Stage 7 마지막에 딱 한 번만!)
        #[arg(long)]
        include_sealed: bool,
    },
    /// 아직 임베딩이 없는 항목을 임베딩
    Embed,
    /// 텍스트 파일에서 LLM 으로 후보를 뽑아 승인 큐에 넣기 (저장은 하지 않는다)
