#[tokio::main]
async fn main() -> Result<()> {
    let cli = Cli::parse();
    let db = Db::open(&cli.db).with_context(|| format!("{} 을 열지 못했어요", cli.db.display()))?;

    match cli.cmd {
        Cmd::Add { kind, scope, body, why, force } => {
            let new = NewItem { kind, scope, body, why, source: "manual".into() };
            let dups = if force {
                vec![]
            } else {
                let emb = AnyEmbedder::from_env()?;
                manage::similar_to(&db, &emb, &new.body, manage::DUPLICATE_THRESHOLD).await?
            };
            if let Some(&(old_id, sim)) = dups.first() {
                for (id, s) in &dups {
                    if let Some(it) = db.get(*id)? {
                        println!("비슷한 항목: #{id} [{}/{}] {}  ({s:.2})", it.kind.as_str(), it.scope, it.body);
                    }
                }
                let answer = ask(&format!("#{old_id} 와 {sim:.2} 만큼 비슷해요. [s] #{old_id} 를 대체 / [n] 새로 넣기 / [c] 취소: "))?;
                match answer.as_str() {
                    "s" => {
                        let id = db.supersede(old_id, &new)?;
                        println!("#{old_id} 를 대체함: #{id}");
                    }
                    "n" => {
                        let id = db.insert(&new)?;
                        println!("추가됨: #{id}");
                    }
                    _ => println!("취소했어요"),
                }
            } else {
                let id = db.insert(&new)?;
                println!("추가됨: #{id}");
            }
        }
        Cmd::Supersede { old_id, body, why } => {
            let Some(old) = db.get(old_id)? else { bail!("#{old_id} 항목이 없어요") };
            let id = db.supersede(
                old_id,
                &NewItem { kind: old.kind, scope: old.scope, body, why, source: "manual".into() },
            )?;
            println!("#{old_id} 를 대체함: #{id}");
        }
        Cmd::Confirm { id } => {
            db.confirm(id)?;
            println!("#{id} 확인함");
        }
        Cmd::Stale => {
            for it in manage::stale_now(&db)? {
                println!(
                    "#{:<4} [{}/{}] {}  ({}일 기준)",
                    it.id,
                    it.kind.as_str(),
                    it.scope,
                    it.body,
                    manage::stale_after_days(it.kind)
                );
            }
        }
        Cmd::Conflicts => {
            let emb = AnyEmbedder::from_env()?;
            let pairs =
                manage::similar_pairs(&db, emb.model_id(), manage::CONFLICT_THRESHOLD, manage::DUPLICATE_THRESHOLD)?;
            for (a, b, s) in pairs {
                if let (Some(x), Some(y)) = (db.get(a)?, db.get(b)?) {
                    println!("[{}] ({s:.2})\n  #{a} {}\n  #{b} {}", x.scope, x.body, y.body);
                }
            }
        }
        Cmd::List { kind, scope, status } => {
            for it in db.list(kind, scope.as_deref(), status)? {
                println!("#{:<4} [{}/{}] {}", it.id, it.kind.as_str(), it.scope, it.body);
            }
        }
        Cmd::Get { id } => match db.get(id)? {
            Some(it) => print_item(&it),
            None => bail!("#{id} 항목이 없어요"),
        },
        Cmd::Import { file } => {
            let text = fs::read_to_string(&file)
                .with_context(|| format!("{} 을 읽지 못했어요", file.display()))?;
            match import::parse_lines(&text) {
                Ok(items) => {
                    let n = db.insert_many(&items)?;
                    println!("{n}개를 가져왔어요");
                }
                Err(errors) => {
                    for (line, msg) in &errors {
                        eprintln!("{}:{line}: {msg}", file.display());
                    }
                    bail!("{}줄에 문제가 있어서 아무것도 넣지 않았어요", errors.len());
                }
            }
        }
        Cmd::EvalCheck { file } => {
            let text = fs::read_to_string(&file)
                .with_context(|| format!("{} 을 읽지 못했어요", file.display()))?;
            let qs = eval::load_questions(&text)?;
            let missing = eval::missing_answers(&db, &qs)?;
            for (q, id) in &missing {
                eprintln!("정답 id #{id} 가 DB에 없어요: {q}");
            }
            if !missing.is_empty() {
                bail!("{}건의 정답 id를 고치세요", missing.len());
            }
            let sealed = qs.iter().filter(|q| q.sealed).count();
            println!("질문 {}개 (봉인 {}개), 정답 id 모두 확인됨", qs.len(), sealed);
        }
        Cmd::Search { query, mode, k, history } => {
            let hits = if history { search_history(&db, &query, k)? } else { run_search(&db, mode, &query, k).await? };
            for (i, hit) in hits.iter().enumerate() {
                if let Some(it) = db.get(hit.id)? {
                    let status = if it.status == Status::Active { String::new() } else { format!(" ({})", it.status.as_str()) };
                    println!("{:>2}) [{}/{}] {}{status}  ({:.2})", i + 1, it.kind.as_str(), it.scope, it.body, hit.score);
                }
            }
        }
        Cmd::Eval { file, mode, include_sealed } => {
            let text = fs::read_to_string(&file)
                .with_context(|| format!("{} 을 읽지 못했어요", file.display()))?;
            let qs = eval::load_questions(&text)?;
            let emb = AnyEmbedder::from_env()?;
            let report = match mode {
                Mode::Fts => eval::run_eval(&FtsRetriever { db: &db }, &qs, include_sealed).await?,
                Mode::Vector => eval::run_eval(&VectorRetriever { db: &db, embedder: &emb }, &qs, include_sealed).await?,
                Mode::Hybrid => {
                    let h = HybridRetriever {
                        a: FtsRetriever { db: &db },
                        b: VectorRetriever { db: &db, embedder: &emb },
                        rrf_k: 60.0,
                        fetch: 20,
                    };
                    eval::run_eval(&h, &qs, include_sealed).await?
                }
            };

            println!("{:<14} {:>3} {:>9} {:>9} {:>7}", "유형", "n", "Recall@3", "Recall@5", "MRR");
            let line = |name: &str, r: &eval::Row| {
                println!("{:<14} {:>3} {:>9.2} {:>9.2} {:>7.2}", name, r.n, r.recall3, r.recall5, r.mrr);
                if let Some(e) = r.empty_rate {
                    println!("{:<14}     (정답 없음 중 빈 결과 비율 {:.2})", "", e);
                }
            };
            line("전체", &report.overall);
            for (tag, row) in &report.by_tag {
                line(tag, row);
            }
        }
        Cmd::Extract { file } => {
            let text = fs::read_to_string(&file)
                .with_context(|| format!("{} 을 읽지 못했어요", file.display()))?;
            let (clean, hidden) = extract::redact(&text);
            if hidden > 0 {
                eprintln!("비밀처럼 보이는 부분 {hidden}곳을 가리고 보냅니다");
            }
            let llm = ClaudeClient::from_env()?;
            let (system, user) = extract::build_prompt(&clean);
            let (raw, usage) = llm.complete(&system, &user).await?;
            pending::record_usage(&db, llm.model(), usage.input_tokens, usage.output_tokens)?;

            let (candidates, rejected) = extract::parse_candidates(&raw);
            for (i, reason) in &rejected {
                eprintln!("후보 {i} 을 버렸어요: {reason}");
            }
            let source_ref = file.display().to_string();
            for c in &candidates {
                pending::add_pending(&db, c, Some(&source_ref))?;
            }
            let (calls, input, output) = pending::usage_total(&db)?;
            println!(
                "후보 {}개를 승인 큐에 넣었어요 (버림 {}개). 이번 토큰: 입력 {} / 출력 {}, 누적 {}회 {} / {}",
                candidates.len(),
                rejected.len(),
                usage.input_tokens,
                usage.output_tokens,
                calls,
                input,
                output
            );
        }
        Cmd::Review => {
            let queue = pending::waiting(&db)?;
            if queue.is_empty() {
                println!("대기 중인 후보가 없어요");
            }
            for p in queue {
                let c = &p.candidate;
                println!("\n#{} [{}/{}] {}", p.id, c.kind.as_str(), c.scope, c.body);
                println!("    이유: {}  출처: {}", c.why.as_deref().unwrap_or("-"), p.source_ref.as_deref().unwrap_or("-"));
                match ask("[a] 승인 / [e] 수정 후 승인 / [r] 거절 / [s] 건너뛰기 / [q] 끝: ")?.as_str() {
                    "a" => println!("승인: #{}", pending::approve(&db, p.id, None)?),
                    "e" => {
                        let body = ask("새 본문 (비우면 그대로): ")?;
                        let why = ask("새 이유 (비우면 그대로): ")?;
                        let edited = Candidate {
                            body: if body.is_empty() { c.body.clone() } else { body },
                            why: if why.is_empty() { c.why.clone() } else { Some(why) },
                            ..c.clone()
                        };
                        println!("승인: #{}", pending::approve(&db, p.id, Some(&edited))?);
                    }
                    "r" => {
                        pending::reject(&db, p.id)?;
                        println!("거절함");
                    }
                    "q" => break,
                    _ => println!("건너뜀"),
                }
            }
        }
        Cmd::Embed => {
            let n = embed_missing(&db, &AnyEmbedder::from_env()?, 32).await?;
            println!("{n}개를 임베딩했어요");
        }
    }
    Ok(())
}

/// 한 줄을 물어 받는다. 입력이 끝났으면 빈 문자열.
fn ask(prompt: &str) -> Result<String> {
    print!("{prompt}");
    io::stdout().flush()?;
    let mut line = String::new();
    io::stdin().lock().read_line(&mut line)?;
    Ok(line.trim().to_string())
}

fn print_item(it: &Item) {
    println!("id         {}", it.id);
    println!("kind       {}", it.kind.as_str());
    println!("scope      {}", it.scope);
    println!("body       {}", it.body);
    println!("why        {}", it.why.as_deref().unwrap_or("-"));
    println!("source     {}", it.source);
    if let Some(old) = it.supersedes_id {
        println!("supersedes #{old}");
    }
    println!("status     {}", it.status.as_str());
    println!("created_at {} (UTC 초)", it.created_at);
}

