//! core 의 에러를 HTTP 상태로 바꾼다. 내부 에러의 상세는 응답에 담지 않는다.

use axum::Json;
use axum::http::StatusCode;
use axum::response::{IntoResponse, Response};
use serde_json::json;

#[derive(Debug)]
pub enum ApiError {
    Unauthorized,
    BadRequest(String),
    NotFound(i64),
    /// 상세는 서버 로그에만 남기고 응답에는 담지 않는다
    Internal,
}

impl From<mnemo_core::Error> for ApiError {
    fn from(e: mnemo_core::Error) -> Self {
        match e {
            mnemo_core::Error::NotFound(id) => ApiError::NotFound(id),
            mnemo_core::Error::Invalid(msg) => ApiError::BadRequest(msg),
            other => {
                eprintln!("내부 오류: {other}");
                ApiError::Internal
            }
        }
    }
}

impl IntoResponse for ApiError {
    fn into_response(self) -> Response {
        let (status, msg) = match self {
            ApiError::Unauthorized => (StatusCode::UNAUTHORIZED, "인증이 필요해요".to_string()),
            ApiError::BadRequest(msg) => (StatusCode::BAD_REQUEST, msg),
            ApiError::NotFound(id) => (StatusCode::NOT_FOUND, format!("#{id} 를 찾지 못했어요")),
            ApiError::Internal => (
                StatusCode::INTERNAL_SERVER_ERROR,
                "내부 오류가 발생했어요".to_string(),
            ),
        };
        (status, Json(json!({ "error": msg }))).into_response()
    }
}

//! 동기 DB(rusqlite)를 비동기 서버에서 쓰는 두 가지 방법.
//! `Connection` 은 다른 스레드로 옮길 수는 있지만(Send) 여러 스레드가 함께 쓸 수는 없다(!Sync).
//!
//! - `Mutex`: 연결 하나를 Mutex 로 감싸고, 잠그고 쓰는 일은 `spawn_blocking` 스레드에서 한다.
//!   코드가 짧다. 대신 잠금을 오래 쥐면 다른 요청이 줄을 선다.
//! - `Actor`: 전용 스레드 하나가 연결을 독점하고, 채널로 일을 받아 차례대로 처리한다.
//!   잠금이 없고 DB 를 만지는 곳이 한 군데뿐이다. 대신 채널과 응답 통로가 필요하다.

use std::sync::{Arc, Mutex, mpsc};

use mnemo_core::Db;
use tokio::sync::oneshot;

use crate::error::ApiError;

type Job = Box<dyn FnOnce(&Db) + Send>;

#[derive(Clone)]
pub enum DbHandle {
    Mutex(Arc<Mutex<Db>>),
    Actor(mpsc::Sender<Job>),
}

impl DbHandle {
    pub fn mutex(db: Db) -> Self {
        Self::Mutex(Arc::new(Mutex::new(db)))
    }

    pub fn actor(db: Db) -> Self {
        let (tx, rx) = mpsc::channel::<Job>();
        std::thread::spawn(move || {
            for job in rx {
                job(&db);
            }
        });
        Self::Actor(tx)
    }

    /// DB 를 쓰는 동기 함수를 서버의 async 스레드를 막지 않고 실행한다.
    pub async fn run<T, F>(&self, f: F) -> Result<T, ApiError>
    where
        T: Send + 'static,
        F: FnOnce(&Db) -> mnemo_core::Result<T> + Send + 'static,
    {
        match self {
            Self::Mutex(m) => {
                let m = Arc::clone(m);
                tokio::task::spawn_blocking(move || {
                    let db = m.lock().map_err(|_| ApiError::Internal)?;
                    f(&db).map_err(ApiError::from)
                })
                .await
                .map_err(|_| ApiError::Internal)?
            }
            Self::Actor(tx) => {
                let (done_tx, done_rx) = oneshot::channel();
                tx.send(Box::new(move |db: &Db| {
                    let _ = done_tx.send(f(db));
                }))
                .map_err(|_| ApiError::Internal)?;
                done_rx
                    .await
                    .map_err(|_| ApiError::Internal)?
                    .map_err(ApiError::from)
            }
        }
    }
}

//! 모든 요청에 `Authorization: Bearer <토큰>` 을 요구한다.
//! 비교는 일정한 시간에 걸리는 방식으로 하고, 토큰은 어디에도 찍지 않는다.

use axum::extract::{Request, State};
use axum::http::header::AUTHORIZATION;
use axum::middleware::Next;
use axum::response::Response;
use subtle::ConstantTimeEq;

use crate::AppState;
use crate::error::ApiError;

pub async fn require_token(
    State(state): State<AppState>,
    req: Request,
    next: Next,
) -> Result<Response, ApiError> {
    let given = req
        .headers()
        .get(AUTHORIZATION)
        .and_then(|v| v.to_str().ok())
        .and_then(|v| v.strip_prefix("Bearer "))
        .unwrap_or("");
    if token_matches(given, &state.token) {
        Ok(next.run(req).await)
    } else {
        Err(ApiError::Unauthorized)
    }
}

/// 앞부분이 맞을수록 오래 걸리는 일반 비교 대신, 내용과 상관없이 같은 시간에 비교한다.
/// (길이가 다르면 바로 false 라 길이는 드러날 수 있다)
pub fn token_matches(given: &str, expected: &str) -> bool {
    !expected.is_empty() && bool::from(given.as_bytes().ct_eq(expected.as_bytes()))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn compares_tokens() {
        assert!(token_matches("abc", "abc"));
        assert!(!token_matches("abd", "abc"));
        assert!(!token_matches("", "abc"));
        assert!(!token_matches("", ""));
    }
}

//! 엔드포인트: 검색, 항목 목록/조회/추가, 대기 후보 목록/승인/거절.

use axum::Json;
use axum::extract::{Path, Query, State};
use mnemo_core::embed::Embedder;
use mnemo_core::hybrid::rrf;
use mnemo_core::search::fts_search;
use mnemo_core::vector::rank_vectors;
use mnemo_core::{Item, Kind, NewItem, Status, pending};
use serde::Deserialize;
use serde_json::{Value, json};

use crate::AppState;
use crate::error::ApiError;

const MAX_QUERY_CHARS: usize = 500;
const MAX_BODY_CHARS: usize = 500;
/// 각 검색기에서 몇 개씩 가져와 합칠지
const FETCH: usize = 20;
const RRF_K: f64 = 60.0;

#[derive(Deserialize)]
pub struct SearchParams {
    q: String,
    k: Option<usize>,
}

/// 혼합 검색. 디버그 화면(Stage 13)을 위해 키워드/벡터 순위도 함께 돌려준다.
pub async fn search(
    State(state): State<AppState>,
    Query(p): Query<SearchParams>,
) -> Result<Json<Value>, ApiError> {
    let q = p.q.trim().to_string();
    if q.is_empty() || q.chars().count() > MAX_QUERY_CHARS {
        return Err(ApiError::BadRequest(format!(
            "q 는 1~{MAX_QUERY_CHARS}자여야 해요"
        )));
    }
    let k = p.k.unwrap_or(5);
    if !(1..=50).contains(&k) {
        return Err(ApiError::BadRequest("k 는 1~50 이어야 해요".into()));
    }

    // 질문 임베딩은 네트워크를 쓸 수 있으니 DB 밖에서 먼저 한다
    let qv = state
        .embedder
        .embed(std::slice::from_ref(&q))
        .await?
        .remove(0);
    let vector = rank_vectors(&state.vectors, &qv, FETCH);

    let out = state
        .db
        .run(move |db| {
            let fts = fts_search(db, &q, FETCH)?;
            let fts_ids: Vec<i64> = fts.iter().map(|s| s.id).collect();
            let vec_ids: Vec<i64> = vector.iter().map(|s| s.id).collect();
            let mut results = Vec::new();
            for (id, score) in rrf(&[fts_ids.clone(), vec_ids.clone()], RRF_K) {
                // 벡터는 시작할 때 읽어 둔 것이라, 그 뒤에 대체된 항목은 여기서 거른다
                if let Some(item) = db.get(id)?.filter(|it| it.status == Status::Active) {
                    results.push(json!({ "item": item, "score": score }));
                }
                if results.len() == k {
                    break;
                }
            }
            Ok(json!({ "results": results, "debug": { "fts": fts_ids, "vector": vec_ids } }))
        })
        .await?;
    Ok(Json(out))
}

#[derive(Deserialize)]
pub struct ListParams {
    kind: Option<String>,
    scope: Option<String>,
    status: Option<String>,
}

pub async fn list_items(
    State(state): State<AppState>,
    Query(p): Query<ListParams>,
) -> Result<Json<Vec<Item>>, ApiError> {
    let kind = p.kind.as_deref().map(parse_kind).transpose()?;
    let status = match p.status.as_deref() {
        Some(s) => s.parse::<Status>().map_err(ApiError::BadRequest)?,
        None => Status::Active,
    };
    let scope = p.scope;
    let items = state
        .db
        .run(move |db| db.list(kind, scope.as_deref(), status))
        .await?;
    Ok(Json(items))
}

pub async fn get_item(
    State(state): State<AppState>,
    Path(id): Path<i64>,
) -> Result<Json<Item>, ApiError> {
    let item = state.db.run(move |db| db.get(id)).await?;
    item.map(Json).ok_or(ApiError::NotFound(id))
}

#[derive(Deserialize)]
pub struct NewItemBody {
    kind: String,
    scope: String,
    body: String,
    why: Option<String>,
}

pub async fn add_item(
    State(state): State<AppState>,
    Json(b): Json<NewItemBody>,
) -> Result<Json<Value>, ApiError> {
    let new = NewItem {
        kind: parse_kind(&b.kind)?,
        scope: non_empty("scope", &b.scope, 64)?,
        body: non_empty("body", &b.body, MAX_BODY_CHARS)?,
        why: b
            .why
            .map(|w| w.trim().to_string())
            .filter(|w| !w.is_empty()),
        source: "api".into(),
    };
    let id = state.db.run(move |db| db.insert(&new)).await?;
    Ok(Json(json!({ "id": id })))
}

pub async fn list_pending(State(state): State<AppState>) -> Result<Json<Value>, ApiError> {
    let list = state.db.run(pending::waiting).await?;
    let out: Vec<Value> = list
        .into_iter()
        .map(|p| {
            json!({
                "id": p.id,
                "kind": p.candidate.kind,
                "scope": p.candidate.scope,
                "body": p.candidate.body,
                "why": p.candidate.why,
                "source_ref": p.source_ref,
                "proposed_at": p.proposed_at,
            })
        })
        .collect();
    Ok(Json(Value::Array(out)))
}

pub async fn approve_pending(
    State(state): State<AppState>,
    Path(id): Path<i64>,
) -> Result<Json<Value>, ApiError> {
    let item_id = state
        .db
        .run(move |db| pending::approve(db, id, None))
        .await?;
    Ok(Json(json!({ "item_id": item_id })))
}

pub async fn reject_pending(
    State(state): State<AppState>,
    Path(id): Path<i64>,
) -> Result<Json<Value>, ApiError> {
    state.db.run(move |db| pending::reject(db, id)).await?;
    Ok(Json(json!({ "rejected": id })))
}

fn parse_kind(s: &str) -> Result<Kind, ApiError> {
    s.parse().map_err(ApiError::BadRequest)
}

fn non_empty(name: &str, s: &str, max: usize) -> Result<String, ApiError> {
    let s = s.trim();
    if s.is_empty() || s.chars().count() > max {
        return Err(ApiError::BadRequest(format!(
            "{name} 는 1~{max}자여야 해요"
        )));
    }
    Ok(s.to_string())
}

//! mnemo HTTP API. core 를 감싸기만 하고, 판단은 core 에 둔다.

pub mod auth;
pub mod db_access;
pub mod error;
pub mod routes;

use std::sync::Arc;

use axum::extract::DefaultBodyLimit;
use axum::http::header::{AUTHORIZATION, CONTENT_TYPE};
use axum::http::{HeaderValue, Method};
use axum::routing::{get, post};
use axum::{Router, middleware};
use mnemo_core::embed::AnyEmbedder;
use tower_http::cors::CorsLayer;

pub use db_access::DbHandle;

/// 핸들러들이 함께 쓰는 값. 전부 서버가 시작할 때 한 번 준비한다.
#[derive(Clone)]
pub struct AppState {
    pub db: DbHandle,
    pub embedder: Arc<AnyEmbedder>,
    /// 시작할 때 한 번 읽어 둔 active 항목의 벡터
    pub vectors: Arc<Vec<(i64, Vec<f32>)>>,
    /// 환경변수에서 읽은 인증 토큰
    pub token: Arc<String>,
}

/// 요청 본문 크기 제한 (바이트)
const BODY_LIMIT: usize = 16 * 1024;

pub fn app(state: AppState, cors_origin: Option<HeaderValue>) -> Router {
    let mut router = Router::new()
        .route("/search", get(routes::search))
        .route("/items", get(routes::list_items).post(routes::add_item))
        .route("/items/{id}", get(routes::get_item))
        .route("/pending", get(routes::list_pending))
        .route("/pending/{id}/approve", post(routes::approve_pending))
        .route("/pending/{id}/reject", post(routes::reject_pending))
        .layer(middleware::from_fn_with_state(
            state.clone(),
            auth::require_token,
        ))
        .layer(DefaultBodyLimit::max(BODY_LIMIT))
        .with_state(state);

    // 프론트엔드가 다른 출처에서 부를 때만, 그 출처 하나만 허용한다
    if let Some(origin) = cors_origin {
        router = router.layer(
            CorsLayer::new()
                .allow_origin(origin)
                .allow_methods([Method::GET, Method::POST])
                .allow_headers([AUTHORIZATION, CONTENT_TYPE]),
        );
    }
    router
}

#[cfg(test)]
mod tests {
    use super::*;
    use axum::body::Body;
    use axum::http::{Request, StatusCode};
    use http_body_util::BodyExt;
    use mnemo_core::embed::{Embedder, FakeEmbedder, embed_missing};
    use mnemo_core::vector::load_vectors;
    use mnemo_core::{Db, Kind, NewItem};
    use serde_json::Value;
    use tower::ServiceExt;

    const TOKEN: &str = "test-token-123";

    async fn state_with(handle: fn(Db) -> DbHandle) -> AppState {
        let db = Db::open_in_memory().unwrap();
        for body in ["deploy on friday is banned", "use sqlite for storage"] {
            db.insert(&NewItem {
                kind: Kind::Work,
                scope: "global".into(),
                body: body.into(),
                why: None,
                source: "t".into(),
            })
            .unwrap();
        }
        let embedder = AnyEmbedder::Fake(FakeEmbedder { dim: 128 });
        embed_missing(&db, &embedder, 10).await.unwrap();
        let vectors = load_vectors(&db, embedder.model_id()).unwrap();
        AppState {
            db: handle(db),
            embedder: Arc::new(embedder),
            vectors: Arc::new(vectors),
            token: Arc::new(TOKEN.into()),
        }
    }

    async fn call(state: AppState, req: Request<Body>) -> (StatusCode, Value) {
        let res = app(state, None).oneshot(req).await.unwrap();
        let status = res.status();
        let bytes = res.into_body().collect().await.unwrap().to_bytes();
        (
            status,
            serde_json::from_slice(&bytes).unwrap_or(Value::Null),
        )
    }

    fn get_req(uri: &str, token: Option<&str>) -> Request<Body> {
        let mut b = Request::builder().uri(uri);
        if let Some(t) = token {
            b = b.header("authorization", format!("Bearer {t}"));
        }
        b.body(Body::empty()).unwrap()
    }

    #[tokio::test]
    async fn rejects_missing_or_wrong_token() {
        let s = state_with(DbHandle::mutex).await;
        let (st, _) = call(s.clone(), get_req("/items", None)).await;
        assert_eq!(st, StatusCode::UNAUTHORIZED);
        let (st, _) = call(s, get_req("/items", Some("wrong"))).await;
        assert_eq!(st, StatusCode::UNAUTHORIZED);
    }

    #[tokio::test]
    async fn search_works_with_both_db_handles() {
        for handle in [DbHandle::mutex as fn(Db) -> DbHandle, DbHandle::actor] {
            let s = state_with(handle).await;
            let (st, body) = call(s, get_req("/search?q=friday%20deploy&k=1", Some(TOKEN))).await;
            assert_eq!(st, StatusCode::OK);
            assert_eq!(body["results"][0]["item"]["id"], 1);
            assert_eq!(body["results"].as_array().unwrap().len(), 1);
            assert!(body["debug"]["fts"].is_array());
        }
    }

    #[tokio::test]
    async fn maps_errors_to_status() {
        let s = state_with(DbHandle::actor).await;
        let (st, _) = call(s.clone(), get_req("/items/999", Some(TOKEN))).await;
        assert_eq!(st, StatusCode::NOT_FOUND);
        let (st, _) = call(s.clone(), get_req("/items?kind=secret", Some(TOKEN))).await;
        assert_eq!(st, StatusCode::BAD_REQUEST);
        let (st, _) = call(s.clone(), get_req("/search?q=", Some(TOKEN))).await;
        assert_eq!(st, StatusCode::BAD_REQUEST);

        let req = Request::builder()
            .method("POST")
            .uri("/items")
            .header("authorization", format!("Bearer {TOKEN}"))
            .header("content-type", "application/json")
            .body(Body::from(
                r#"{"kind":"work","scope":"global","body":"   "}"#,
            ))
            .unwrap();
        let (st, _) = call(s, req).await;
        assert_eq!(st, StatusCode::BAD_REQUEST);
    }

    #[tokio::test]
    async fn internal_error_hides_details() {
        let s = state_with(DbHandle::mutex).await;
        s.db.run(|db| Ok(db.conn().execute_batch("DROP TABLE pending")?))
            .await
            .unwrap();
        let (st, body) = call(s, get_req("/pending", Some(TOKEN))).await;
        assert_eq!(st, StatusCode::INTERNAL_SERVER_ERROR);
        assert!(!body.to_string().contains("pending"));
    }

    #[tokio::test]
    async fn adds_and_reads_item() {
        let s = state_with(DbHandle::mutex).await;
        let req = Request::builder()
            .method("POST")
            .uri("/items")
            .header("authorization", format!("Bearer {TOKEN}"))
            .header("content-type", "application/json")
            .body(Body::from(
                r#"{"kind":"pref","scope":"global","body":"keep functions small"}"#,
            ))
            .unwrap();
        let (st, body) = call(s.clone(), req).await;
        assert_eq!(st, StatusCode::OK);
        let id = body["id"].as_i64().unwrap();
        let (st, body) = call(s, get_req(&format!("/items/{id}"), Some(TOKEN))).await;
        assert_eq!(st, StatusCode::OK);
        assert_eq!(body["kind"], "pref");
        assert_eq!(body["source"], "api");
    }
}

use std::sync::Arc;

use anyhow::{Context, Result, bail};
use axum::http::HeaderValue;
use mnemo_core::Db;
use mnemo_core::embed::{AnyEmbedder, Embedder};
use mnemo_core::vector::load_vectors;
use mnemo_server::{AppState, DbHandle, app};

/// 설정은 전부 환경변수로 받는다.
/// MNEMO_TOKEN(필수), MNEMO_DB(기본 mnemo.db), MNEMO_ADDR(기본 127.0.0.1:8080),
/// MNEMO_DB_ACCESS(mutex | actor, 기본 mutex), MNEMO_CORS_ORIGIN(선택), 임베더 설정은 cli 와 같다.
#[tokio::main]
async fn main() -> Result<()> {
    let token = std::env::var("MNEMO_TOKEN").context("환경변수 MNEMO_TOKEN 이 필요해요")?;
    if token.len() < 16 {
        bail!("MNEMO_TOKEN 은 16자 이상이어야 해요");
    }
    let db_path = std::env::var("MNEMO_DB").unwrap_or_else(|_| "mnemo.db".into());
    let addr = std::env::var("MNEMO_ADDR").unwrap_or_else(|_| "127.0.0.1:8080".into());

    let db = Db::open(db_path.as_ref()).with_context(|| format!("{db_path} 을 열지 못했어요"))?;
    // 임베더와 벡터는 시작할 때 한 번 준비한다
    let embedder = AnyEmbedder::from_env()?;
    let vectors = load_vectors(&db, embedder.model_id())?;
    eprintln!(
        "벡터 {}개를 읽었어요 (모델 {})",
        vectors.len(),
        embedder.model_id()
    );

    let handle = match std::env::var("MNEMO_DB_ACCESS").as_deref() {
        Ok("actor") => DbHandle::actor(db),
        Ok("mutex") | Err(_) => DbHandle::mutex(db),
        Ok(other) => bail!("MNEMO_DB_ACCESS 는 mutex 또는 actor 예요: {other}"),
    };
    let cors = match std::env::var("MNEMO_CORS_ORIGIN") {
        Ok(o) => Some(HeaderValue::from_str(&o).context("MNEMO_CORS_ORIGIN 형식이 잘못됐어요")?),
        Err(_) => None,
    };

    let state = AppState {
        db: handle,
        embedder: Arc::new(embedder),
        vectors: Arc::new(vectors),
        token: Arc::new(token),
    };
    let listener = tokio::net::TcpListener::bind(&addr).await?;
    eprintln!("{addr} 에서 듣고 있어요");
    axum::serve(listener, app(state, cors)).await?;
    Ok(())
}
